}

'use client';
/**
 * One lamp for the whole page. At rest it hangs at the upper left, 38° above the page: the same resting light the
 * liquid-glass lens uses, so DOM shadows and the WebGL glass agree. On fine pointers the visitor carries it: every
 * element marked `data-lit` gets `--lx` / `--ly` (the light's direction projected on the page, pointing from the
 * element toward the lamp), high and close when the pointer is near, low and raking when it is far. CSS turns those
 * into shadows that fall away from the lamp and highlights that face it.
 *
 * One rAF loop for all elements; it reads every rect first, then writes custom properties, skips unchanged values,
 * only visits elements near the viewport and sleeps once every light has settled. Reduced motion and touch: no
 * loop, the CSS rest values apply.
 */
import { useEffect, type RefObject } from 'react';

/** Resting light, the lens recipe's: azimuth (-0.6, -0.8) at 38° elevation, projected on the page. */
export const REST_LIGHT = { x: -0.473, y: -0.63 } as const;
const DEG = Math.PI / 180;
const smooth = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };

interface Lamp { x: number; y: number; tx: number; ty: number; written: string }

export function usePageLight(root: RefObject<HTMLElement | null>, enabled: boolean): void {
  useEffect(() => {
    const host = root.current;
    if (!host || !enabled || typeof window === 'undefined') return;
    const fine = window.matchMedia?.('(hover: hover) and (pointer: fine)').matches;
    if (!fine) return;

    const lamps = new Map<HTMLElement, Lamp>();
    const near = new Set<HTMLElement>();
    let pointer: { x: number; y: number } | null = null;
    let raf = 0;
    let last = 0;

    const io = typeof IntersectionObserver !== 'undefined'
      ? new IntersectionObserver((entries) => {
        for (const e of entries) {
          const el = e.target as HTMLElement;
          if (e.isIntersecting) near.add(el); else near.delete(el);
        }
        wake();
      }, { rootMargin: '160px' })
      : null;
    const collect = () => {
      const now = new Set(Array.from(host.querySelectorAll<HTMLElement>('[data-lit]')));
      for (const el of lamps.keys()) if (!now.has(el)) { lamps.delete(el); near.delete(el); io?.unobserve(el); }
      for (const el of now) if (!lamps.has(el)) {
        lamps.set(el, { x: REST_LIGHT.x, y: REST_LIGHT.y, tx: REST_LIGHT.x, ty: REST_LIGHT.y, written: '' });
        if (io) io.observe(el); else near.add(el);
      }
    };
    collect();
    // Sections mount lazily (the reel, the rating): pick up new lit elements as they arrive (debounced).
    let pending = 0;
    const mo = new MutationObserver(() => { window.clearTimeout(pending); pending = window.setTimeout(collect, 120); });
    mo.observe(host, { childList: true, subtree: true });

    const tick = (now: number) => {
      raf = 0;
      const dt = Math.min(0.05, last ? (now - last) / 1000 : 1 / 60);
      last = now;
      // Read pass: every target from the rects, before any write.
      const visible = Array.from(near);
      const rects = visible.map((el) => el.getBoundingClientRect());
      visible.forEach((el, i) => {
        const L = lamps.get(el);
        if (!L) return;
        if (!pointer) { L.tx = REST_LIGHT.x; L.ty = REST_LIGHT.y; return; }
        const r = rects[i];
        const dx = pointer.x - (r.left + r.width / 2), dy = pointer.y - (r.top + r.height / 2);
        const dist = Math.hypot(dx, dy);
        const size = Math.max(r.width, r.height);
        if (dist < 1) return;
        const el2 = (60 - 32 * smooth(size * 0.25, size * 1.6 + 500, dist)) * DEG;
        L.tx = (dx / dist) * Math.cos(el2);
        L.ty = (dy / dist) * Math.cos(el2);
      });
      // Write pass: ease toward the targets (a lamp has some weight), skip values that did not change.
      const k = 1 - Math.exp(-dt * 7);
      let busy = false;
      for (const el of visible) {
        const L = lamps.get(el);
        if (!L) continue;
        L.x += (L.tx - L.x) * k;
        L.y += (L.ty - L.y) * k;
        if (Math.abs(L.tx - L.x) > 0.002 || Math.abs(L.ty - L.y) > 0.002) busy = true;
        else { L.x = L.tx; L.y = L.ty; }
        const key = `${L.x.toFixed(3)} ${L.y.toFixed(3)}`;
        if (key !== L.written) {
          L.written = key;
          el.style.setProperty('--lx', L.x.toFixed(3));
          el.style.setProperty('--ly', L.y.toFixed(3));
        }
      }
      if (busy) raf = requestAnimationFrame(tick);
      else last = 0;
    };
    function wake() { if (!raf && !document.hidden) raf = requestAnimationFrame(tick); }

    const onMove = (e: PointerEvent) => {
      if (e.pointerType !== 'mouse' && e.pointerType !== 'pen') return;
      pointer = { x: e.clientX, y: e.clientY };
      wake();
    };
    const onOut = (e: PointerEvent) => { if (!e.relatedTarget) { pointer = null; wake(); } };
    const onScroll = () => { if (pointer) wake(); };
    window.addEventListener('pointermove', onMove, { passive: true });
    document.addEventListener('pointerout', onOut, { passive: true });
    window.addEventListener('scroll', onScroll, { passive: true, capture: true });
    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(pending);
      io?.disconnect();
      mo.disconnect();
      window.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerout', onOut);
      window.removeEventListener('scroll', onScroll, { capture: true });
      for (const el of lamps.keys()) { el.style.removeProperty('--lx'); el.style.removeProperty('--ly'); }
    };
  }, [root, enabled]);
}

/**
 * The light table under the glass: Lead & Lag's manifesto, "Nothing stops dead.", set as a staircase the studio's
 * ball bounces down (onion-skinned, shot on twos) until it lands as the full stop, with the animator's furniture
 * around it: a 12-field guide, peg holes, an easing graph, a spring response, a spacing chart and a timeline.
 *
 * Laid out once in design units from the current theme tokens and the stage's aspect ratio, then rendered twice
 * from the same items: canvas2d for the lens texture and SVG for the no-WebGL fallback and the loading poster.
 * The diagrams plot the motion tokens this page really uses (emphasized easing, spring.pop), not invented numbers.
 */
import { easing, spring } from '../../../motion';

export interface Palette {
  paper: string; paper2: string; ink: string; muted: string; line: string; signal: string;
  /** Dark surface (night palette or dark theme). */
  dark: boolean;
}
export interface Fonts { display: string; text: string; serif: string; mono: string }
export interface Theme { palette: Palette; fonts: Fonts }

type Rgba = [number, number, number, number];
let probe: CanvasRenderingContext2D | null | undefined;
const ctx2d = (): CanvasRenderingContext2D | null => (probe === undefined ? (probe = document.createElement('canvas').getContext('2d')) : probe);

/** Any CSS colour → [r, g, b, a], normalised by the browser's own parser. */
function toRgba(css: string): Rgba {
  const g = ctx2d();
  if (!g) return [0, 0, 0, 1];
  g.fillStyle = '#000';
  g.fillStyle = css;
  const v = String(g.fillStyle);
  if (v.startsWith('#')) return [parseInt(v.slice(1, 3), 16), parseInt(v.slice(3, 5), 16), parseInt(v.slice(5, 7), 16), 1];
  const m = v.match(/[\d.]+/g)?.map(Number) ?? [0, 0, 0, 1];
  return [m[0], m[1], m[2], m[3] ?? 1];
}
const hex = ([r, g, b]: Rgba): string => `#${[r, g, b].map((c) => Math.round(Math.min(255, Math.max(0, c))).toString(16).padStart(2, '0')).join('')}`;
/** `a` mixed toward `b` by t, as an opaque hex colour. */
export function mix(a: string, b: string, t: number): string {
  const x = toRgba(a), y = toRgba(b);
  return hex([x[0] + (y[0] - x[0]) * t, x[1] + (y[1] - x[1]) * t, x[2] + (y[2] - x[2]) * t, 1]);
}
function luminance(css: string): number {
  const [r, g, b] = toRgba(css);
  const lin = (c: number) => { const s = c / 255; return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}

/** Theme tokens as resolved on `el` (the demo's own day or night palette), with the contract's fallbacks. */
export function readTheme(el: Element): Theme {
  const cs = getComputedStyle(el);
  const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  const paper = v('--mk-surface', '#fbf9f4');
  return {
    palette: {
      paper, paper2: v('--mk-surface-2', '#e9e5da'), ink: v('--mk-ink', '#11110f'), muted: v('--mk-ink-muted', '#5c5a52'),
      line: v('--mk-line', '#11110f24'), signal: v('--mk-signal', '#bf2f09'), dark: luminance(paper) < 0.2,
    },
    fonts: {
      display: v('--mk-font-display', 'ui-sans-serif, system-ui, sans-serif'), text: v('--mk-font-text', 'ui-sans-serif, system-ui, sans-serif'),
      serif: v('--mk-font-serif', 'Georgia, serif'), mono: v('--mk-font-mono', 'ui-monospace, monospace'),
    },
  };
}

/** Faces the composition draws with: load them before the texture is drawn so it never bakes a fallback font. */
export const manifestoFonts = (f: Fonts): string[] => [`800 100px ${f.display}`, `italic 400 100px ${f.serif}`, `500 20px ${f.mono}`];

export type Align = 'left' | 'center' | 'right';
export interface TextItem {
  k: 'text'; x: number; y: number; text: string; family: string; size: number; weight: number;
  italic?: boolean; /** em */ tracking: number; fill: string; align: Align; alpha?: number;
}
interface Paint { fill?: string; stroke?: string; width?: number; alpha?: number; dash?: readonly number[] }
export type Item =
  | ({ k: 'rect'; x: number; y: number; w: number; h: number; r?: number } & Paint)
  /** Light-table glow: an elliptical radial gradient. */
  | { k: 'glow'; cx: number; cy: number; rx: number; ry: number; from: string; to: string }
  | ({ k: 'path'; d: string; cap?: 'round' | 'butt' } & Paint)
  | ({ k: 'circle'; cx: number; cy: number; r: number } & Paint)
  | ({ k: 'ellipse'; cx: number; cy: number; rx: number; ry: number; /** deg */ rot: number } & Paint)
  /** Text set round a circle, clockwise from `start` (deg, 0 = top). */
  | { k: 'ring'; cx: number; cy: number; r: number; text: string; family: string; size: number; weight: number; tracking: number; fill: string; start: number; alpha?: number }
  | TextItem;
export interface Composition { width: number; height: number; items: readonly Item[] }

export const fontOf = (t: { family: string; size: number; weight: number; italic?: boolean }): string =>
  `${t.italic ? 'italic ' : ''}${t.weight} ${t.size}px ${t.family}`;

interface Measure {
  width(text: string, font: string, tracking?: number, size?: number): number;
  /** Ascent of a glyph above the baseline (cap height for "H", x-height for "x"). */
  ascent(glyph: string, font: string): number;
}
function canvasMeasure(): Measure {
  return {
    width: (text, font, tracking = 0, size = 0) => {
      const g = ctx2d();
      const raw = g ? ((g.font = font), g.measureText(text).width) : text.length * 10;
      return raw + tracking * size * Math.max(0, text.length - 1);
    },
    ascent: (glyph, font) => { const g = ctx2d(); if (!g) return 70; g.font = font; return g.measureText(glyph).actualBoundingBoxAscent || 70; },
  };
}

const f1 = (n: number) => Math.round(n * 10) / 10;
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** Cubic bezier easing (CSS semantics) sampled at x, by bisection on the x polynomial. */
function bezierAt([x1, y1, x2, y2]: readonly number[], x: number): number {
  const bx = (t: number) => 3 * (1 - t) * (1 - t) * t * x1 + 3 * (1 - t) * t * t * x2 + t * t * t;
  const by = (t: number) => 3 * (1 - t) * (1 - t) * t * y1 + 3 * (1 - t) * t * t * y2 + t * t * t;
  let lo = 0, hi = 1;
  for (let i = 0; i < 40; i++) { const m = (lo + hi) / 2; if (bx(m) < x) lo = m; else hi = m; }
  return by((lo + hi) / 2);
}

/** Step response of a damped spring (Motion semantics), position at t seconds; target 1. */
function springAt(c: { stiffness: number; damping: number; mass: number }, t: number): number {
  const w0 = Math.sqrt(c.stiffness / c.mass), z = c.damping / (2 * Math.sqrt(c.stiffness * c.mass));
  if (z < 1) {
    const wd = w0 * Math.sqrt(1 - z * z);
    return 1 - Math.exp(-z * w0 * t) * (Math.cos(wd * t) + ((z * w0) / wd) * Math.sin(wd * t));
  }
  return 1 - Math.exp(-w0 * t) * (1 + w0 * t);
}

interface Pt { x: number; y: number }
interface Ghost extends Pt { vx: number; vy: number; contact?: number; frame: number }

/**
 * One parabolic hop from P to Q under gravity g (units per frame²), rising `h` above P first. Samples every `step`
 * frames from `t0` (frames already elapsed), excluding Q itself.
 */
function hop(P: Pt, Q: Pt, h: number, g: number, step: number, t0: number, out: Ghost[]): number {
  const v0 = Math.sqrt(2 * g * h);
  const ta = v0 / g;
  const drop = h + (Q.y - P.y);
  const T = ta + Math.sqrt(Math.max(0, 2 * drop / g));
  const first = Math.ceil(t0 / step) * step - t0;
  for (let t = first; t < T - 0.35; t += step) {
    out.push({ x: P.x + ((Q.x - P.x) * t) / T, y: P.y - v0 * t + 0.5 * g * t * t, vx: (Q.x - P.x) / T, vy: -v0 + g * t, frame: Math.round(t0 + t) + 1 });
  }
  return t0 + T;
}

/**
 * Lay out the sheet at the stage's aspect ratio (width / height) so cover-fitting never crops its marks: a landscape
 * sheet 600 units tall whose width follows the aspect, or below 1.15 a portrait sheet 400 units wide.
 */
export function composeManifesto(aspect: number, { palette: p, fonts: f }: Theme, words: readonly [string, string, string]): Composition {
  const m = canvasMeasure();
  const portrait = aspect < 1.15;
  const W = portrait ? 400 : Math.round(clamp(600 * aspect, 690, 1700));
  const H = portrait ? Math.round(clamp(400 / aspect, 360, 780)) : 600;
  const M = portrait ? 22 : 46;
  const items: Item[] = [];
  const faint = mix(p.paper, p.ink, p.dark ? 0.1 : 0.075);
  const hair = mix(p.paper, p.ink, p.dark ? 0.2 : 0.16);
  const mono = (s: string, x: number, y: number, align: Align, fill = p.muted, size = portrait ? 8.5 : 10.5, alpha?: number) =>
    items.push({ k: 'text', x, y, text: s.toUpperCase(), family: f.mono, size, weight: 500, tracking: 0.12, fill, align, alpha });

  // Paper on a light table: brighter where the lamp underneath is, falling off to the edges.
  items.push({ k: 'rect', x: 0, y: 0, w: W, h: H, fill: p.paper });
  items.push({ k: 'glow', cx: W * 0.42, cy: H * 0.5, rx: W * 0.62, ry: H * 0.78, from: mix(p.paper, '#ffffff', p.dark ? 0.06 : 0.6), to: p.paper });

  // 12-field guide: nested frames round the centre, numbered every second field.
  const fgc = { x: W / 2, y: H / 2 + (portrait ? 0 : 8) };
  const ratio = portrait ? 3 / 4 : 16 / 9;
  for (let k = 1; k <= 6; k++) {
    const h = (H - (portrait ? 70 : 90)) * (k / 6);
    const w = h * ratio;
    if (w > W - 2 * M + 1) continue;
    items.push({ k: 'rect', x: f1(fgc.x - w / 2), y: f1(fgc.y - h / 2), w: f1(w), h: f1(h), stroke: faint, width: 1 });
    mono(String(k * 2), fgc.x + w / 2 - 4, fgc.y - h / 2 + 11, 'right', hair, portrait ? 7 : 8);
  }
  items.push({ k: 'path', d: `M${fgc.x - 9} ${fgc.y}H${fgc.x + 9}M${fgc.x} ${fgc.y - 9}V${fgc.y + 9}`, stroke: hair, width: 1 });

  // Peg holes punched through the sheet: the lamp shines through them.
  const pegY = portrait ? 11 : 15;
  const hole = mix(p.paper, '#ffffff', p.dark ? 0.16 : 0.85);
  const rim = mix(p.paper, p.ink, p.dark ? 0.35 : 0.22);
  const pegGap = portrait ? 46 : 70;
  items.push({ k: 'circle', cx: W / 2, cy: pegY + 6, r: portrait ? 4.5 : 6, fill: hole, stroke: rim, width: 1 });
  for (const s of [-1, 1]) items.push({ k: 'rect', x: W / 2 + s * pegGap - (portrait ? 11 : 16), y: pegY + (portrait ? 2 : 1.5), w: portrait ? 22 : 32, h: portrait ? 8 : 9, r: portrait ? 4 : 4.5, fill: hole, stroke: rim, width: 1 });

  // Sheet header and its rule.
  const top = portrait ? 38 : 46;
  mono(portrait ? 'Lead & Lag · sheet 01' : 'Lead & Lag — sheet 01 · manifesto', M, top, 'left', p.ink);
  mono(portrait ? '24 fps' : 'Sc 01 · take 03 · 24 fps', W - M, top, 'right');
  items.push({ k: 'path', d: `M${M} ${top + 10}H${W - M}`, stroke: p.ink, width: 1, alpha: 0.85 });

  // ── The staircase: each line ends further right, so the ball can bounce down the steps. ──────────────────────
  const disp = (size: number) => ({ family: f.display, size, weight: 800 });
  const ital = (size: number) => ({ family: f.serif, size, weight: 400, italic: true });
  const SERIF = 1.2;
  const per = { d: m.width(words[0], fontOf(disp(100)), -0.035, 100) / 100, s: m.width(words[1], fontOf(ital(100 * SERIF)), -0.01, 100 * SERIF) / 100, e: m.width(words[2].replace(/\.$/, ''), fontOf(disp(100)), -0.035, 100) / 100 };
  const capR = m.ascent('H', fontOf(disp(100))) / 100;
  const xhD = m.ascent('x', fontOf(disp(100))) / 100;
  const ascD = m.ascent('d', fontOf(disp(100))) / 100;
  const xhS = m.ascent('x', fontOf(ital(100 * SERIF))) / 100;
  const step = 1; // each line ends this many em further right than the one above: the ball's steps
  // Line ends (em from the left margin): E1 = w1, E2 = E1 + step, E3 = E2 + step (+ the full stop).
  const ballR = 0.088;
  const ends = { e1: per.d, e2: per.d + step, e3: per.d + 2 * step };
  const blockW = ends.e3 + 0.06 + ballR * 2 + 0.05;
  const colW = portrait ? 0 : clamp(W * 0.25, 240, 340);
  const textRight = portrait ? W - M : W - M - colW - 56;
  const lead = 0.93;
  const headTop = top + (portrait ? 40 : 44);
  const roomH = portrait ? H * 0.5 : H - headTop - 96;
  const S = Math.max(24, Math.min((textRight - M) / blockW, roomH / (capR + 2 * lead + 0.22)));
  const b1 = headTop + capR * S;
  const b2 = b1 + lead * S;
  const b3 = b2 + lead * S;
  const x1 = M - 0.02 * S;
  const x2 = M + (ends.e2 - per.s) * S;
  const x3 = M + (ends.e3 - per.e) * S;
  items.push({ k: 'text', x: x1, y: b1, text: words[0], ...disp(S), tracking: -0.035, fill: p.ink, align: 'left' });
  items.push({ k: 'text', x: x2, y: b2, text: words[1], ...ital(S * SERIF), tracking: -0.01, fill: p.ink, align: 'left' });
  items.push({ k: 'text', x: x3, y: b3, text: words[2].replace(/\.$/, ''), ...disp(S), tracking: -0.035, fill: p.ink, align: 'left' });

  // ── The ball drops in past the end of "Nothing", bounces off the last "s", then the "d", and lands as the stop. ─
  const r = ballR * S;
  const C1 = { x: M + (ends.e2 - 0.19) * S, y: b2 - xhS * S - r };
  const C2 = { x: M + (ends.e3 - 0.17) * S, y: b3 - ascD * S - r };
  const R = { x: M + (ends.e3 + 0.06) * S + r, y: b3 - r };
  const g = 0.021 * S; // a fall of one em takes about ten frames
  const start = { x: M + (ends.e1 + 0.16) * S, y: top + 22 + r };
  const ghosts: Ghost[] = [];
  const EVERY = 3; // one drawing every third frame keeps the onion skin legible
  let t = hop(start, C1, 0, g, EVERY, 0, ghosts);
  ghosts.push({ ...C1, vx: 0, vy: 0, contact: b2 - xhS * S, frame: Math.round(t) + 1 });
  t = hop(C1, C2, 0.42 * S, g, EVERY, t, ghosts);
  ghosts.push({ ...C2, vx: 0, vy: 0, contact: b3 - ascD * S, frame: Math.round(t) + 1 });
  t = hop(C2, R, 0.14 * S, g, EVERY, t, ghosts);
  const visible = ghosts;
  // The arc, dashed through every drawing.
  const arc = [...visible, { ...R }].map((q, i) => `${i ? 'L' : 'M'}${f1(q.x)} ${f1(q.y)}`).join('');
  items.push({ k: 'path', d: arc, stroke: p.muted, width: 1, dash: [3, 4], alpha: 0.7 });
  const n = visible.length;
  visible.forEach((q, i) => {
    const a = 0.34 + 0.5 * (i / Math.max(1, n - 1));
    const paint = { fill: p.paper, stroke: p.ink, width: portrait ? 1 : 1.3, alpha: a };
    if (q.contact !== undefined) {
      // Contact: squashed flat against the letter it lands on, wider than it is tall.
      items.push({ k: 'ellipse', cx: f1(q.x), cy: f1(q.contact - r * 0.7), rx: f1(r * 1.32), ry: f1(r * 0.7), rot: 0, ...paint });
      items.push({ k: 'path', d: `M${f1(q.x + r * 1.9)} ${f1(q.contact - r * 2.2)}l${f1(r * 0.42)} ${f1(r * 0.42)} ${f1(-r * 0.42)} ${f1(r * 0.42)} ${f1(-r * 0.42)} ${f1(-r * 0.42)}z`, fill: p.signal });
    } else {
      // In flight: stretched along the velocity, more so the faster it falls.
      const speed = Math.hypot(q.vx, q.vy) / (g * 10);
      const st = clamp(speed * 0.15, 0, 0.28);
      const rot = (Math.atan2(q.vy, q.vx) * 180) / Math.PI;
      items.push({ k: 'ellipse', cx: f1(q.x), cy: f1(q.y), rx: f1(r * (1 + st)), ry: f1(r / (1 + st)), rot: f1(rot), ...paint });
    }
    if (i % 2 === 0 && q.contact === undefined) mono(String(q.frame).padStart(2, '0'), q.x + r * 1.55, q.y - r * 0.9, 'left', p.muted, portrait ? 6.5 : 8);
  });

  // Fig. 0 and the studio stamp, in the pocket under "Nothing" and left of the stairs.
  const pocketX = M;
  const pocketR = M + (ends.e2 - per.s) * S - 18;
  if (pocketR - pocketX > (portrait ? 110 : 200)) {
    const ny = b1 + (portrait ? 0.62 : 0.55) * S;
    const sz = portrait ? 6.8 : 9.5;
    mono('Fig. 0 — the full stop', pocketX, ny, 'left', p.ink, sz);
    mono(portrait ? 'one ball · two contacts' : 'one ball · two contacts · one hold', pocketX, ny + sz * 1.75, 'left', p.muted, sz);
    if (!portrait) mono('squash on contact, stretch in flight', pocketX, ny + sz * 3.5, 'left', p.muted, sz);
  }
  // The full stop: settled, round, with a soft contact shadow falling away from the upper-left lamp.
  items.push({ k: 'ellipse', cx: f1(R.x + r * 0.22), cy: f1(b3 + r * 0.08), rx: f1(r * 1.05), ry: f1(r * 0.2), rot: 0, fill: p.ink, alpha: p.dark ? 0.5 : 0.2 });
  items.push({ k: 'circle', cx: f1(R.x), cy: f1(R.y), r: f1(r), fill: p.signal });
  const hold = `${String(Math.round(t) + 1).padStart(2, '0')} · hold`;
  const holdSize = portrait ? 6.5 : 8;
  if (R.x + r * 1.8 + m.width(hold.toUpperCase(), `500 ${holdSize}px ${f.mono}`, 0.12, holdSize) < W - M) mono(hold, R.x + r * 1.8, R.y + r * 0.4, 'left', p.signal, holdSize);
  else mono(hold, R.x + r, b3 + holdSize * 1.9, 'right', p.signal, holdSize);

  // ── Diagrams: the tokens this page moves with. ─────────────────────────────────────────────────────────────────
  const curve = (x0: number, y0: number, w: number, h: number, fn: (u: number) => number, samples = 48) => {
    let d = '';
    for (let i = 0; i <= samples; i++) { const u = i / samples; d += `${i ? 'L' : 'M'}${f1(x0 + u * w)} ${f1(y0 + h - fn(u) * h)}`; }
    return d;
  };
  const easingFig = (x0: number, y0: number, b: number, small: boolean) => {
    for (let i = 1; i < 4; i++) items.push({ k: 'path', d: `M${f1(x0 + (b * i) / 4)} ${y0}V${y0 + b}M${x0} ${f1(y0 + (b * i) / 4)}H${x0 + b}`, stroke: faint, width: 1 });
    items.push({ k: 'path', d: `M${x0} ${y0}V${y0 + b}H${x0 + b}`, stroke: p.ink, width: 1 });
    const [ax, ay, bx, by] = easing.emphasized;
    const P1 = { x: x0 + ax * b, y: y0 + b - ay * b }, P2 = { x: x0 + bx * b, y: y0 + b - by * b };
    items.push({ k: 'path', d: `M${x0} ${y0 + b}L${f1(P1.x)} ${f1(P1.y)}M${x0 + b} ${y0}L${f1(P2.x)} ${f1(P2.y)}`, stroke: p.signal, width: 1.2 });
    items.push({ k: 'path', d: curve(x0, y0, b, b, (u) => bezierAt(easing.emphasized, u)), stroke: p.ink, width: small ? 1.6 : 2.2, cap: 'round' });
    for (const q of [P1, P2]) items.push({ k: 'circle', cx: f1(q.x), cy: f1(q.y), r: small ? 2.6 : 3.4, fill: p.paper, stroke: p.signal, width: 1.4 });
    for (const q of [{ x: x0, y: y0 + b }, { x: x0 + b, y: y0 }]) items.push({ k: 'circle', cx: q.x, cy: q.y, r: small ? 2.4 : 3, fill: p.ink });
    mono(small ? 'Fig. 1 — ease' : 'Fig. 1 — ease · emphasized', x0, y0 - 10, 'left', p.ink, small ? 7 : 9);
    mono(easing.emphasized.join(', '), x0, y0 + b + (small ? 13 : 17), 'left', p.muted, small ? 7 : 9);
  };
  const springFig = (x0: number, y0: number, w: number, h: number, small: boolean) => {
    const c = spring.pop;
    const T = 0.9;
    const peak = Math.max(...Array.from({ length: 200 }, (_, i) => springAt(c, (i / 199) * T)));
    const top1 = y0 + h * 0.18; // the target line sits below the top so the overshoot has room
    const k = (h - (top1 - y0)) / 1; // units per 1.0 of travel
    const yOf = (v: number) => y0 + h - v * k;
    items.push({ k: 'path', d: `M${x0} ${y0}V${y0 + h}H${x0 + w}`, stroke: p.ink, width: 1 });
    items.push({ k: 'path', d: `M${x0} ${f1(yOf(1))}H${x0 + w}`, stroke: p.muted, width: 1, dash: [4, 4] });
    let d = '';
    for (let i = 0; i <= 90; i++) { const u = i / 90; d += `${i ? 'L' : 'M'}${f1(x0 + u * w)} ${f1(yOf(springAt(c, u * T)))}`; }
    items.push({ k: 'path', d, stroke: p.signal, width: small ? 1.6 : 2.2, cap: 'round' });
    const over = Math.round((peak - 1) * 100);
    mono(small ? 'Fig. 2 — spring.pop' : 'Fig. 3 — spring.pop · overshoot', x0, y0 - 10, 'left', p.ink, small ? 7 : 9);
    mono(`k ${c.stiffness} · c ${c.damping} · m ${c.mass}${small ? '' : ` · +${over}%`}`, x0, y0 + h + (small ? 13 : 17), 'left', p.muted, small ? 7 : 9);
  };
  const spacingFig = (x0: number, y0: number, len: number) => {
    // Timing chart: nine drawings between two keys, eased (slow out), the breakdown marked.
    items.push({ k: 'path', d: `M${x0} ${y0}V${y0 + len}`, stroke: p.ink, width: 1 });
    for (let i = 0; i <= 8; i++) {
      const y = y0 + bezierAt(easing.emphasized, i / 8) * len;
      const key = i === 0 || i === 8;
      items.push({ k: 'path', d: `M${x0 - (key ? 9 : 6)} ${f1(y)}H${x0 + (key ? 9 : 6)}`, stroke: key ? p.signal : p.ink, width: key ? 1.6 : 1 });
      if (key) items.push({ k: 'circle', cx: x0 + 21, cy: f1(y), r: 7, stroke: p.signal, width: 1.1 });
      if (key) mono(i === 0 ? '1' : '9', x0 + 21, y + 3.2, 'center', p.signal, 8);
    }
    mono('Fig. 2', x0 - 4, y0 - 10, 'left', p.ink, 9);
    mono('spacing', x0 - 4, y0 + len + 17, 'left', p.muted, 9);
  };

  if (!portrait) {
    const cx0 = W - M - colW;
    const b = clamp(colW * 0.44, 104, 140);
    easingFig(cx0, headTop + 22, b, false);
    spacingFig(cx0 + b + clamp(colW * 0.2, 44, 70), headTop + 22, b);
    springFig(cx0, headTop + 22 + b + 74, colW, clamp(H * 0.15, 72, 98), false);
  } else {
    const yRow = b3 + S * 0.55 + 24;
    const room = H - 72 - yRow;
    if (room > 88) {
      const b = clamp(Math.min(room - 34, (W - 2 * M) * 0.3), 60, 104);
      easingFig(M + 2, yRow, b, true);
      springFig(M + b + 34, yRow, W - 2 * M - b - 36, b * 0.8, true);
    }
  }

  // A rubber stamp: honest about the studio, set round a circle and turned against the grid.
  const stampR = portrait ? 25 : 46;
  const stamp = { x: M + stampR + 4, y: b3 - (portrait ? 0.2 : 0.42) * S };
  if (M + (ends.e3 - per.e) * S - (stamp.x + stampR) > 12) {
    items.push({ k: 'circle', cx: f1(stamp.x), cy: f1(stamp.y), r: stampR, stroke: p.signal, width: portrait ? 1.2 : 1.6, alpha: 0.82 });
    items.push({ k: 'circle', cx: f1(stamp.x), cy: f1(stamp.y), r: stampR * 0.66, stroke: p.signal, width: 0.9, alpha: 0.82 });
    items.push({ k: 'ring', cx: f1(stamp.x), cy: f1(stamp.y), r: stampR * 0.79, text: 'Fictional studio · est. 2017 · ', family: f.mono, size: portrait ? 5.4 : 8.6, weight: 600, tracking: 0.14, fill: p.signal, start: -100, alpha: 0.88 });
    items.push({ k: 'text', x: stamp.x, y: stamp.y + stampR * 0.2, text: 'L&L', family: f.serif, size: stampR * 0.56, weight: 400, italic: true, tracking: 0, fill: p.signal, align: 'center', alpha: 0.88 });
  }

  // ── Timeline: 24 frames, keys and breakdowns, the playhead parked on 13. ───────────────────────────────────────
  const ty = H - (portrait ? 30 : 38);
  const tw = W - 2 * M;
  const frames = 24;
  const fx = (i: number) => M + (tw * i) / frames;
  let ticks = '';
  for (let i = 0; i <= frames; i++) ticks += `M${f1(fx(i))} ${ty}V${f1(ty - (i % 6 === 0 ? 11 : 5))}`;
  items.push({ k: 'path', d: `M${M} ${ty}H${W - M}${ticks}`, stroke: p.ink, width: 1 });
  for (let i = 0; i <= frames; i += 6) mono(String(Math.max(1, i)).padStart(2, '0'), fx(i) + 3, ty + (portrait ? 11 : 13), 'left', p.muted, portrait ? 6.5 : 8);
  const diamond = (x: number, y: number, s: number, filled: boolean) =>
    items.push({ k: 'path', d: `M${f1(x)} ${f1(y - s)}L${f1(x + s)} ${f1(y)} ${f1(x)} ${f1(y + s)} ${f1(x - s)} ${f1(y)}Z`, ...(filled ? { fill: p.signal } : { fill: p.paper, stroke: p.signal, width: 1.2 }) });
  const dk = portrait ? 3.4 : 4.6;
  for (const i of [0, 8, 16, 24]) diamond(fx(i), ty - 18, dk, true);
  for (const i of [4, 12, 20]) diamond(fx(i), ty - 18, dk * 0.85, false);
  const ph = fx(13);
  items.push({ k: 'path', d: `M${f1(ph)} ${ty - 30}V${ty + 2}`, stroke: p.signal, width: 1.4 });
  items.push({ k: 'rect', x: f1(ph - 11), y: ty - (portrait ? 40 : 43), w: 22, h: portrait ? 11 : 13, r: 2.5, fill: p.signal });
  mono('13', ph, ty - (portrait ? 31.6 : 33.2), 'center', p.paper, portrait ? 6.5 : 8);
  if (!portrait) {
    mono('Timeline · keys ◆ · breakdowns ◇', W - M, ty - 30, 'right', p.muted, 8.5);
  }

  // Registration marks.
  const reg = portrait ? 9 : 14;
  for (const [cx, cy] of [[reg, reg], [W - reg, reg], [reg, H - reg], [W - reg, H - reg]]) {
    const rr = portrait ? 3.5 : 5.5;
    items.push({ k: 'circle', cx, cy, r: rr, stroke: p.ink, width: 0.9 });
    items.push({ k: 'path', d: `M${cx - rr * 1.8} ${cy}H${cx + rr * 1.8}M${cx} ${cy - rr * 1.8}V${cy + rr * 1.8}`, stroke: p.ink, width: 0.9 });
  }

  return { width: W, height: H, items };
}

/** Cover-fit transform from design units to a cssW × cssH stage (centred, like SVG `xMidYMid slice`). */
export function coverTransform(cssW: number, cssH: number, c: Composition) {
  const s = Math.max(cssW / c.width, cssH / c.height);
  return { s, ox: (cssW - c.width * s) / 2, oy: (cssH - c.height * s) / 2 };
}

/** Draw the composition with canvas2d over a cssW × cssH area (the caller sets any device-pixel scale first). */
export function drawManifesto(g: CanvasRenderingContext2D, cssW: number, cssH: number, c: Composition): void {
  const { s, ox, oy } = coverTransform(cssW, cssH, c);
  g.save();
  g.transform(s, 0, 0, s, ox, oy);
  const spaced = 'letterSpacing' in g;
  const setTracking = (px: number) => { if (spaced) (g as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = `${px}px`; };
  const paint = (it: { fill?: string; stroke?: string; width?: number; alpha?: number; dash?: readonly number[] }, path?: Path2D, cap?: CanvasLineCap) => {
    g.globalAlpha = it.alpha ?? 1;
    if (it.fill) { g.fillStyle = it.fill; if (path) g.fill(path); else g.fill(); }
    if (it.stroke) {
      g.strokeStyle = it.stroke;
      g.lineWidth = it.width ?? 1;
      g.lineCap = cap ?? 'butt';
      g.lineJoin = 'round';
      g.setLineDash(it.dash ? [...it.dash] : []);
      if (path) g.stroke(path); else g.stroke();
    }
    g.globalAlpha = 1;
  };
  for (const it of c.items) {
    switch (it.k) {
      case 'rect': {
        g.beginPath();
        if (it.r && 'roundRect' in g) g.roundRect(it.x, it.y, it.w, it.h, it.r); else g.rect(it.x, it.y, it.w, it.h);
        paint(it);
        break;
      }
      case 'glow': {
        g.save();
        g.translate(it.cx, it.cy);
        g.scale(1, it.ry / it.rx);
        const grad = g.createRadialGradient(0, 0, 0, 0, 0, it.rx);
        grad.addColorStop(0, it.from);
        grad.addColorStop(1, it.to);
        g.fillStyle = grad;
        g.fillRect(-it.rx, -it.rx, it.rx * 2, it.rx * 2);
        g.restore();
        break;
      }
      case 'path': paint(it, new Path2D(it.d), it.cap); break;
      case 'circle': g.beginPath(); g.arc(it.cx, it.cy, it.r, 0, Math.PI * 2); paint(it); break;
      case 'ellipse': g.beginPath(); g.ellipse(it.cx, it.cy, it.rx, it.ry, (it.rot * Math.PI) / 180, 0, Math.PI * 2); paint(it); break;
      case 'ring': {
        g.font = fontOf(it);
        g.fillStyle = it.fill;
        g.globalAlpha = it.alpha ?? 1;
        g.textAlign = 'center';
        g.textBaseline = 'middle';
        setTracking(0);
        let a = (it.start * Math.PI) / 180;
        for (const ch of it.text) {
          const cw = g.measureText(ch).width + it.tracking * it.size;
          a += cw / 2 / it.r;
          g.save();
          g.translate(it.cx + Math.sin(a) * it.r, it.cy - Math.cos(a) * it.r);
          g.rotate(a);
          g.fillText(ch, 0, 0);
          g.restore();
          a += cw / 2 / it.r;
        }
        g.globalAlpha = 1;
        break;
      }
      case 'text':
        g.font = fontOf(it);
        g.fillStyle = it.fill;
        g.globalAlpha = it.alpha ?? 1;
        g.textAlign = it.align;
        g.textBaseline = 'alphabetic';
        setTracking(it.tracking * it.size);
        g.fillText(it.text, it.x, it.y);
        g.globalAlpha = 1;
        break;
    }
  }
  setTracking(0);
  g.restore();
}

/** Character advances for ring text in the SVG renderer (same measuring as the canvas). */
export function ringGlyphs(it: Extract<Item, { k: 'ring' }>): { ch: string; x: number; y: number; deg: number }[] {
  const g = ctx2d();
  const out: { ch: string; x: number; y: number; deg: number }[] = [];
  let a = (it.start * Math.PI) / 180;
  for (const ch of it.text) {
    let w = it.size * 0.6;
    if (g) { g.font = fontOf(it); w = g.measureText(ch).width; }
    const cw = w + it.tracking * it.size;
    a += cw / 2 / it.r;
    out.push({ ch, x: it.cx + Math.sin(a) * it.r, y: it.cy - Math.cos(a) * it.r, deg: (a * 180) / Math.PI });
    a += cw / 2 / it.r;
  }
  return out;
}

'use client';
/**
 * The manifesto sheet as SVG: the same items the lens texture is drawn from, for the no-WebGL fallback (under the
 * recipe's CSS glass) and as the poster that paints first while the WebGL chunk loads.
 */
import { useId, useMemo, useRef, type ReactNode } from 'react';
import { useElementSize } from '../../../motion';
import { composeManifesto, ringGlyphs, type Item, type Theme } from './manifesto';
import { STUDIO } from './content';

const dash = (d?: readonly number[]) => (d ? d.join(' ') : undefined);

function renderItem(it: Item, i: number, uid: string): ReactNode {
  switch (it.k) {
    case 'rect': return <rect key={i} x={it.x} y={it.y} width={it.w} height={it.h} rx={it.r} fill={it.fill ?? 'none'} stroke={it.stroke} strokeWidth={it.width} opacity={it.alpha} strokeDasharray={dash(it.dash)} />;
    case 'glow': return (
      <g key={i}>
        <defs>
          <radialGradient id={`${uid}g${i}`} cx={it.cx} cy={it.cy} r={it.rx} gradientUnits="userSpaceOnUse" gradientTransform={`translate(0 ${it.cy}) scale(1 ${it.ry / it.rx}) translate(0 ${-it.cy})`}>
            <stop offset="0" stopColor={it.from} />
            <stop offset="1" stopColor={it.to} />
          </radialGradient>
        </defs>
        <rect x={it.cx - it.rx} y={it.cy - it.ry} width={it.rx * 2} height={it.ry * 2} fill={`url(#${uid}g${i})`} />
      </g>
    );
    case 'path': return <path key={i} d={it.d} fill={it.fill ?? 'none'} stroke={it.stroke} strokeWidth={it.width} opacity={it.alpha} strokeDasharray={dash(it.dash)} strokeLinecap={it.cap} strokeLinejoin="round" />;
    case 'circle': return <circle key={i} cx={it.cx} cy={it.cy} r={it.r} fill={it.fill ?? 'none'} stroke={it.stroke} strokeWidth={it.width} opacity={it.alpha} />;
    case 'ellipse': return <ellipse key={i} cx={it.cx} cy={it.cy} rx={it.rx} ry={it.ry} transform={it.rot ? `rotate(${it.rot} ${it.cx} ${it.cy})` : undefined} fill={it.fill ?? 'none'} stroke={it.stroke} strokeWidth={it.width} opacity={it.alpha} />;
    case 'ring': return (
      <g key={i} fill={it.fill} opacity={it.alpha} fontFamily={it.family} fontSize={it.size} fontWeight={it.weight} textAnchor="middle" dominantBaseline="central">
        {ringGlyphs(it).map((c, j) => <text key={j} x={c.x} y={c.y} transform={`rotate(${c.deg.toFixed(2)} ${c.x.toFixed(2)} ${c.y.toFixed(2)})`}>{c.ch}</text>)}
      </g>
    );
    case 'text': return (
      <text
        key={i} x={it.x} y={it.y} fill={it.fill} opacity={it.alpha} fontFamily={it.family} fontSize={it.size} fontWeight={it.weight}
        fontStyle={it.italic ? 'italic' : undefined} letterSpacing={it.tracking * it.size}
        textAnchor={it.align === 'left' ? 'start' : it.align === 'right' ? 'end' : 'middle'}
      >{it.text}</text>
    );
  }
}

/** The sheet, cover-fitted to its box. `version` re-lays it out after the fonts load. */
export function ManifestoSvg({ theme, version, className }: { theme: Theme | null; version: number; className?: string }) {
  const box = useRef<HTMLDivElement>(null);
  const { width, height } = useElementSize(box);
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, '');
  const comp = useMemo(
    () => (theme && width > 0 && height > 0 ? composeManifesto(width / height, theme, STUDIO.manifesto) : null),
    // version: fonts loaded, measure again
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [theme, width, height, version],
  );
  return (
    <div ref={box} className={className} aria-hidden="true">
      {comp ? (
        <svg viewBox={`0 0 ${comp.width} ${comp.height}`} preserveAspectRatio="xMidYMid slice" focusable="false" width="100%" height="100%" style={{ display: 'block' }}>
          {comp.items.map((it, i) => renderItem(it, i, uid))}
        </svg>
      ) : null}
    </div>
  );
}

'use client';
/**
 * Birb, the studio mascot, sitting in the screening room: the rive-state-machine recipe's RiveCanvas with birb.riv,
 * driven only from the DOM. Adapted from the recipe's BirdStage: Birb looks up when the pointer comes in above its
 * head (or on Look up), dances while the reel plays (or on Dance), and has a Pause control because its idle loop runs
 * for longer than five seconds. Under reduced motion Birb holds a still frame; Dance, Look up and Play still animate
 * because they are explicit, and Birb settles back to a still frame afterwards.
 */
import { useCallback, useEffect, useRef, useState, type PointerEvent } from 'react';
import type { DeprecationId } from '@rive-app/canvas-lite';
import { duration as D, useStudioMotion } from '../../../motion';
import { RiveCanvas, type RiveCanvasApi } from '../../../effects/rive-state-machine';
import { useNear } from './near';
import s from './stage.module.css';

const BIRB = { src: '/rive/birb.riv', artboard: 'birb', stateMachine: 'birb' } as const;
/** birb artboard geometry in its 600 × 600 units (measured by the recipe): body x 111–486, eyes at y ≈ 200. */
const ART = { size: 600, cx: 299, eyeY: 200, half: 188 };
const QUIET: readonly DeprecationId[] = ['state-machine-inputs', 'state-change-events'];
const SAY: Record<string, string> = { idle: 'idling', lookUp: 'looking up', slowDance: 'dancing' };
const SAFETY_MS = 4000;

export function Mascot({ reelPlaying }: { reelPlaying: boolean }) {
  const { reduced } = useStudioMotion();
  const api = useRef<RiveCanvasApi | null>(null);
  const box = useRef<HTMLDivElement>(null);
  const near = useNear(box);
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const [dance, setDance] = useState(false);
  const [playing, setPlaying] = useState(!reduced);
  const [state, setState] = useState('idle');
  const [said, setSaid] = useState({ text: '', n: 0 });
  const paused = !playing;
  const dancing = dance || reelPlaying;
  const reactive = !reduced && ready && playing;

  const live = useRef({ reduced, settle: false, seen: false, inZone: false });
  live.current.reduced = reduced;
  const timer = useRef<number | undefined>(undefined);
  const clearTimer = () => { if (timer.current !== undefined) { window.clearTimeout(timer.current); timer.current = undefined; } };
  useEffect(() => clearTimer, []);
  const holdStill = () => { clearTimer(); live.current.settle = false; setPlaying(false); };
  const playThenSettle = (seen: boolean, safetyMs?: number) => {
    clearTimer();
    Object.assign(live.current, { settle: true, seen });
    setPlaying(true);
    if (safetyMs) timer.current = window.setTimeout(holdStill, safetyMs);
  };

  const firstReduced = useRef(reduced);
  useEffect(() => {
    if (firstReduced.current === reduced) return;
    firstReduced.current = reduced;
    clearTimer();
    live.current.settle = false;
    setPlaying(!reduced);
  }, [reduced]);

  // The boolean input mirrors the toggle and the reel (also when the file finishes loading after a press).
  useEffect(() => {
    const input = api.current?.input('dance');
    if (input) input.value = dancing;
  }, [dancing, ready]);

  // The reel is an explicit Play: Birb joins in even when its own loop is paused or motion is reduced.
  const prevReel = useRef(reelPlaying);
  useEffect(() => {
    if (prevReel.current === reelPlaying) return;
    prevReel.current = reelPlaying;
    if (reelPlaying) {
      if (reduced) { if (!playing) playThenSettle(false); } else setPlaying(true);
      say('Birb is dancing to the reel.');
    } else if (!dance && reduced && (live.current.settle || !playing)) playThenSettle(true, SAFETY_MS);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reelPlaying]);

  const say = (text: string) => setSaid((x) => ({ text, n: x.n + 1 }));

  const onStateChange = useCallback((states: string[]) => {
    const st = states[states.length - 1];
    if (!st) return;
    setState(st);
    const l = live.current;
    if (st !== 'idle') { l.seen = true; return; }
    if (l.reduced && l.settle && l.seen) {
      clearTimer();
      timer.current = window.setTimeout(holdStill, D.slow);
    }
  }, []);

  const toggleDance = () => {
    const next = !dance;
    setDance(next);
    if (!reduced) setPlaying(true);
    else if (next) { if (!playing) playThenSettle(false); }
    else if (!reelPlaying && (!playing || live.current.settle)) playThenSettle(true, SAFETY_MS);
  };
  const lookUp = (from: 'button' | 'pointer') => {
    const input = api.current?.input('look up');
    if (from === 'button') {
      if (!reduced) setPlaying(true);
      else if (!playing || live.current.settle) playThenSettle(false, dancing ? undefined : SAFETY_MS);
      say(ready ? 'Birb looks up.' : 'Birb is still loading.');
    }
    input?.fire();
  };
  const togglePlay = () => {
    clearTimer();
    live.current.settle = false;
    setPlaying(!playing);
    say(playing ? 'Birb paused.' : 'Birb playing.');
  };

  const onPointer = (e: PointerEvent<HTMLDivElement>) => {
    if (!reactive || (e.target as Element).closest('button')) return;
    const b = box.current?.getBoundingClientRect();
    if (!b) return;
    const sc = Math.min(b.width, b.height) / ART.size;
    const eyeX = b.left + (b.width - ART.size * sc) / 2 + ART.cx * sc;
    const eyeY = b.top + (b.height - ART.size * sc) + ART.eyeY * sc;
    const half = ART.half * sc;
    const dx = e.clientX - eyeX, dy = eyeY - e.clientY;
    const l = live.current;
    const inside = dy > 0 && Math.abs(dx) < half + dy * 0.8;
    const outside = dy < -half * 0.2 || Math.abs(dx) > half * 1.25 + Math.max(0, dy) * 0.8;
    if (inside && !l.inZone) { l.inZone = true; lookUp('pointer'); } else if (outside) l.inZone = false;
  };

  const word = failed ? 'unavailable' : !ready ? 'loading' : paused ? 'paused' : (SAY[state] ?? state);
  return (
    <figure className={s.mascot} aria-labelledby="ll-birb-cap">
      <div className={s.mascotStage} data-lit="" onPointerMove={onPointer} onPointerDown={onPointer} onPointerLeave={() => { live.current.inZone = false; }}>
        <span className={s.mascotPool} aria-hidden="true" />
        <div ref={box} className={s.mascotBox}>
          {near ? <RiveCanvas
            className={s.fill}
            src={BIRB.src}
            artboard={BIRB.artboard}
            stateMachine={BIRB.stateMachine}
            fit="contain"
            alignment="bottomCenter"
            paused={paused}
            quietDeprecations={QUIET}
            label={`Birb, the studio mascot: a round blue cartoon bird, ${word}`}
            loading={<span className={s.mascotNote}>Birb is on the way</span>}
            fallback={<p className={s.mascotNote}>Birb could not load here (the Rive runtime or birb.riv is unavailable). The controls still work.</p>}
            onReady={(a) => { api.current = a; setReady(true); setFailed(false); }}
            onError={() => { api.current = null; setReady(false); setFailed(true); }}
            onStateChange={onStateChange}
          /> : <span className={s.mascotWaiting}><span className={s.mascotNote}>Birb is on the way</span></span>}
        </div>
        <button type="button" className={s.roundButton} data-cursor="magnet" onClick={togglePlay} aria-label={paused ? 'Play Birb' : 'Pause Birb'}>
          {paused
            ? <svg viewBox="0 0 20 20" width="16" height="16" aria-hidden="true"><path d="M6.5 4.5v11l9-5.5z" fill="currentColor" /></svg>
            : <svg viewBox="0 0 20 20" width="16" height="16" aria-hidden="true"><path d="M6 4.5h2.6v11H6zM11.4 4.5H14v11h-2.6z" fill="currentColor" /></svg>}
        </button>
      </div>
      <figcaption id="ll-birb-cap" className={s.mascotCap}>
        <span className={s.mascotName}>Birb <span className={s.mascotState}><i data-live={(!paused && ready) || undefined} />{word}</span></span>
        <span className={s.mascotControls}>
          <button type="button" className={s.chip} aria-pressed={dance} onClick={toggleDance}>
            <span className={s.eq} aria-hidden="true" data-on={(dancing && !paused) || undefined}><i /><i /><i /></span>Dance
          </button>
          <button type="button" className={s.chip} onClick={() => lookUp('button')}>
            <svg viewBox="0 0 20 20" width="16" height="16" aria-hidden="true"><path d="M10 15.5v-11M5.5 9 10 4.5 14.5 9" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>
            Look up
          </button>
        </span>
      </figcaption>
      <p className={s.srOnly} role="status">{said.text}{said.n % 2 ? ' ' : ''}</p>
    </figure>
  );
}

'use client';
import { useEffect, useState, type RefObject } from 'react';

/** True once `ref` comes within `margin` of the viewport (stays true). Used to mount canvases lazily. */
export function useNear(ref: RefObject<Element | null>, margin = '500px'): boolean {
  const [near, setNear] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || near) return;
    if (typeof IntersectionObserver === 'undefined') { setNear(true); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setNear(true); io.disconnect(); } }, { rootMargin: margin });
    io.observe(el);
    return () => io.disconnect();
  }, [ref, margin, near]);
  return near;
}

'use client';
/**
 * "How did this page feel?" — rating_animation.riv through the rive-state-machine recipe's RiveCanvas, under a native
 * radio group laid exactly over the drawn stars (the recipe's RatingStars geometry). Hover, focus and a touch drag
 * preview; a click, tap, release or arrow key commits. The artwork keeps its lights and darks but takes its hue from
 * the page's signal colour (luminosity blend). Reduced motion stops the state machine and scrubs each state's
 * animation to its last frame under a 160 ms cross-fade.
 */
import { useEffect, useId, useRef, useState, type CSSProperties, type FocusEvent, type PointerEvent } from 'react';
import type { DeprecationId } from '@rive-app/canvas-lite';
import { cssEase, duration as D, useStudioMotion } from '../../../motion';
import { RiveCanvas, type RiveCanvasApi } from '../../../effects/rive-state-machine';
import { FEEL } from './content';
import { useNear } from './near';
import s from './stage.module.css';

const RATING = { src: '/rive/rating_animation.riv', artboard: 'New Artboard', stateMachine: 'State Machine 1' } as const;
const STARS = [1, 2, 3, 4, 5] as const;
const animFor = (n: number) => (n <= 0 ? 'Idle_empty' : n === 1 ? '1_star' : `${n}_stars`);
const QUIET: readonly DeprecationId[] = ['state-machine-inputs', 'state-change-events', 'animation-names', 'scrub'];
const STAR = 'M12 3.2c.4 0 .8.2 1 .6l2.2 4.6 5 .7c.9.1 1.3 1.2.6 1.9l-3.6 3.5.9 5c.2.9-.8 1.6-1.6 1.2L12 18.3l-4.5 2.4c-.8.4-1.8-.3-1.6-1.2l.9-5-3.6-3.5c-.7-.7-.3-1.8.6-1.9l5-.7 2.2-4.6c.2-.4.6-.6 1-.6z';

export function Rating() {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const api = useRef<RiveCanvasApi | null>(null);
  const ghost = useRef<HTMLCanvasElement>(null);
  const burst = useRef<HTMLSpanElement>(null);
  const bandRef = useRef<HTMLDivElement>(null);
  const near = useNear(bandRef);
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const [value, setValue] = useState(0);
  const [preview, setPreview] = useState<number | null>(null);
  const [said, setSaid] = useState({ text: '', n: 0 });
  const shown = preview ?? value;
  const previewing = preview !== null && preview !== value;

  const mode = useRef<'machine' | 'frames'>('machine');
  const first = useRef(true);
  const fade = useRef<Animation | null>(null);
  const ring = useRef<Animation | null>(null);
  useEffect(() => () => { fade.current?.cancel(); ring.current?.cancel(); }, []);
  useEffect(() => {
    const a = api.current;
    if (!ready || !a) return;
    const { rive } = a;
    if (reduced) {
      const g = ghost.current, src = a.canvas;
      if (!first.current && g && src.width && src.height && typeof g.animate === 'function') {
        g.width = src.width;
        g.height = src.height;
        const ctx = g.getContext('2d');
        if (ctx) {
          ctx.clearRect(0, 0, g.width, g.height);
          ctx.drawImage(src, 0, 0);
          fade.current?.cancel();
          fade.current = g.animate([{ opacity: 1 }, { opacity: 0 }], { duration: D.fast, easing: 'linear', fill: 'forwards' });
        }
      }
      const anim = animFor(shown);
      rive.stop();
      rive.pause(anim);
      rive.scrub(anim, 60);
      mode.current = 'frames';
    } else {
      if (mode.current === 'frames') { rive.stop(); rive.play(RATING.stateMachine); mode.current = 'machine'; }
      const input = a.input('rating');
      if (input) input.value = shown;
    }
    first.current = false;
  }, [shown, reduced, ready]);

  const say = (text: string) => setSaid((x) => ({ text, n: x.n + 1 }));
  const committed = useRef(0);
  const commit = (n: number) => {
    if (n === committed.current) return;
    committed.current = n;
    setValue(n);
    say(`Rated ${n} out of 5: ${FEEL[n]}. Thank you.`);
    const el = burst.current;
    if (!reduced && el && typeof el.animate === 'function') {
      el.style.setProperty('--at', String(n));
      ring.current?.cancel();
      ring.current = el.animate(
        [
          { transform: 'translate(-50%, -50%) scale(0.6)', opacity: 1, borderWidth: '3px' },
          { transform: 'translate(-50%, -50%) scale(1.3)', opacity: 0.75, borderWidth: '2px', offset: 0.4 },
          { transform: 'translate(-50%, -50%) scale(1.8)', opacity: 0, borderWidth: '1px' },
        ],
        { duration: D.slow + D.base, easing: cssEase('standard') },
      );
    }
  };
  const clear = () => {
    if (!committed.current) return;
    committed.current = 0;
    setValue(0);
    setPreview(null);
    say('Rating cleared.');
  };

  const drag = useRef<number | null>(null);
  const slotAt = (x: number, row: HTMLElement) => {
    const r = row.getBoundingClientRect();
    return Math.min(5, Math.max(1, Math.floor(((x - r.left) / r.width) * 5) + 1));
  };
  const onMove = (e: PointerEvent<HTMLDivElement>) => {
    if (e.pointerType === 'touch' && drag.current !== e.pointerId) return;
    setPreview(slotAt(e.clientX, e.currentTarget));
  };
  const onDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.pointerType !== 'touch') return;
    drag.current = e.pointerId;
    setPreview(slotAt(e.clientX, e.currentTarget));
  };
  const onUp = (e: PointerEvent<HTMLDivElement>) => {
    if (drag.current !== e.pointerId) return;
    drag.current = null;
    commit(slotAt(e.clientX, e.currentTarget));
    setPreview(null);
  };
  const onLeave = (e: PointerEvent<HTMLDivElement>) => {
    if (drag.current === e.pointerId) drag.current = null;
    setPreview(null);
  };
  const onBlur = (e: FocusEvent<HTMLFieldSetElement>) => {
    if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setPreview(null);
  };

  return (
    <div className={s.rating}>
      <fieldset className={s.fieldset} onBlur={onBlur}>
        <legend className={s.legend}>How did this page feel?</legend>
        <div ref={bandRef} className={s.band} data-lit="" data-ready={ready || undefined} data-failed={failed || undefined} data-cursor="none">
          <div className={s.bandArt} aria-hidden="true">
            {STARS.map((i) => (
              <svg key={i} className={s.bandStar} viewBox="0 0 24 24" data-on={i <= shown || undefined} style={{ '--at': i } as CSSProperties}>
                <path d={STAR} />
              </svg>
            ))}
          </div>
          {near ? <RiveCanvas
            className={s.bandCanvas}
            src={RATING.src}
            artboard={RATING.artboard}
            stateMachine={RATING.stateMachine}
            fit="cover"
            paused={reduced}
            quietDeprecations={QUIET}
            onReady={(a) => { api.current = a; first.current = true; mode.current = 'machine'; setReady(true); setFailed(false); }}
            onError={() => { api.current = null; setReady(false); setFailed(true); }}
          /> : null}
          {near ? <canvas ref={ghost} className={s.ghost} aria-hidden="true" /> : null}
          <span ref={burst} className={s.burst} aria-hidden="true" />
          <div className={s.slots} onPointerMove={onMove} onPointerDown={onDown} onPointerUp={onUp} onPointerCancel={onLeave} onPointerLeave={onLeave}>
            {STARS.map((i) => (
              <label key={i} className={s.slot}>
                <input className={s.radio} type="radio" name={`${uid}feel`} value={i} checked={value === i} onChange={() => commit(i)} onFocus={() => setPreview(i)} />
                <span className={s.ring} aria-hidden="true" />
                <span className={s.srOnly}>{i === 1 ? '1 star' : `${i} stars`}: {FEEL[i]}</span>
              </label>
            ))}
          </div>
        </div>
      </fieldset>
      <div className={s.verdict}>
        <p className={s.score} data-preview={previewing || undefined} data-empty={!shown || undefined}>
          <span key={shown} className={s.scoreNum}>{shown || '–'}</span><span className={s.scoreOf}>/ 5</span>
        </p>
        <p className={s.word}>{previewing ? <><span className={s.tag}>Preview</span>{FEEL[shown]}</> : FEEL[value]}</p>
        <button type="button" className={s.textButton} onClick={clear} aria-disabled={!value || undefined}>Clear</button>
      </div>
      <p className={s.ratingNote}>
        {failed
          ? 'The animation could not load, so the page draws the stars. The radio buttons work the same.'
          : 'Hover or focus a star to preview; click, tap, drag or use the arrow keys to rate. Your answer stays in this tab: nothing is sent.'}
      </p>
      <p className={s.srOnly} role="status">{said.text}{said.n % 2 ? ' ' : ''}</p>
    </div>
  );
}

'use client';
/**
 * The showreel: seven shots on one seekable Web Animations timeline (createSequence from the motion kit), so Play,
 * Pause and the scrubber all drive the same clock. Play is the lottie-micro-interactions play ⇄ pause icon. The reel
 * is motion as content, so it only ever moves after Play; under reduced motion each shot holds its final frame and
 * shots change with a 160 ms cross-fade. The timecode and scrubber are written straight to the DOM per frame.
 */
import { useCallback, useEffect, useId, useRef, useState, type CSSProperties } from 'react';
import { createSequence, duration as D, useRafLoop, useStudioMotion, type Sequence } from '../../../motion';
import { ICONS, LottieIcon } from '../../../effects/lottie-micro-interactions';
import { REEL_MS, SHOTS, STUDIO, type ShotId } from './content';
import s from './stage.module.css';

const PLAY = ICONS.play.build(2);
const FPS = 24;
const EASE = {
  out: 'cubic-bezier(0.16, 1, 0.3, 1)',
  enter: 'cubic-bezier(0.05, 0.7, 0.1, 1)',
  exit: 'cubic-bezier(0.3, 0, 0.8, 0.15)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
  overshoot: 'cubic-bezier(0.34, 1.56, 0.64, 1)',
};

export const timecode = (ms: number): string => {
  const f = Math.floor((ms / 1000) * FPS);
  const ss = Math.floor(f / FPS), ff = f % FPS;
  return `${String(Math.floor(ss / 60)).padStart(2, '0')}:${String(ss % 60).padStart(2, '0')}:${String(ff).padStart(2, '0')}`;
};
const shotAt = (ms: number) => SHOTS.reduce((cur, sh) => (ms >= sh.at ? sh : cur), SHOTS[0]);

/** Bounce samples for the ball shot, in the 1600 × 900 viewBox: from off-screen left to the full stop. */
function ballKeys(end: { x: number; y: number }, r: number) {
  const g = 3600; // units / s²
  const floor = end.y;
  const hops = [
    { x0: -120, y0: 150, x1: end.x - 640, apex: 0 },
    { x1: end.x - 230, apex: 300 },
    { x1: end.x - 50, apex: 110 },
    { x1: end.x, apex: 34 },
  ];
  const frames: { t: number; x: number; y: number; sx: number; sy: number; rot: number }[] = [];
  let t = 0, x = hops[0].x0!, y = hops[0].y0!;
  hops.forEach((h, i) => {
    const v0 = i === 0 ? 0 : Math.sqrt(2 * g * h.apex);
    const yStart = i === 0 ? y : floor;
    const T = (v0 + Math.sqrt(v0 * v0 + 2 * g * (floor - yStart))) / g;
    const xStart = x;
    for (let k = 0; k < 12; k++) {
      const u = (k / 12) * T;
      const vy = -v0 + g * u;
      const vx = (h.x1 - xStart) / T;
      const st = Math.min(0.3, Math.hypot(vx, vy) / 5200);
      frames.push({ t: t + u, x: xStart + vx * u, y: yStart - v0 * u + 0.5 * g * u * u, sx: 1 + st, sy: 1 / (1 + st), rot: (Math.atan2(vy, vx) * 180) / Math.PI });
    }
    t += T;
    x = h.x1;
    // Contact: squash flat, then recover (two short frames).
    frames.push({ t, x, y: floor + r * 0.3, sx: 1.34, sy: 0.7, rot: 0 });
    frames.push({ t: t + 0.05, x, y: floor, sx: 0.94, sy: 1.06, rot: 0 });
    t += 0.05;
  });
  frames.push({ t: t + 0.16, x: end.x, y: floor, sx: 1, sy: 1, rot: 0 });
  return { frames, total: t + 0.16 };
}

function build(root: HTMLElement, reduced: boolean): Sequence {
  const q = <T extends Element = HTMLElement>(sel: string) => root.querySelector<T>(sel);
  const qa = (sel: string) => Array.from(root.querySelectorAll<HTMLElement>(sel));
  const seq = createSequence();
  const XF = reduced ? D.fast : 1;
  // Visibility per shot: one animation per element, so earlier and later steps never fight over opacity.
  for (const sh of SHOTS) {
    const el = q(`[data-shot="${sh.id}"]`);
    if (!el) continue;
    const a = XF / sh.len;
    const last = sh.id === 'end';
    seq.add(el, [
      { opacity: 0, offset: 0 }, { opacity: 1, offset: Math.min(0.5, a) },
      { opacity: 1, offset: last ? 1 : 1 - Math.min(0.49, a) }, { opacity: last ? 1 : 0, offset: 1 },
    ], { at: sh.at, duration: sh.len, easing: 'linear' });
  }
  // The full stop sits after the real text, measured now that the fonts have loaded (reduced motion rests there too).
  const ball = q<SVGGElement>('[data-ball]');
  const line = q<SVGTextElement>('[data-ball-line]');
  const R = 22, base = 560;
  let ex = 1352;
  try { const bb = line?.getBBox(); if (bb && bb.width > 0) ex = bb.x + bb.width + 14 + R; } catch { /* not rendered */ }
  const ey = base - R;
  if (ball) ball.style.transform = `translate(${ex.toFixed(1)}px, ${ey}px)`;
  q('[data-ball-shadow]')?.setAttribute('cx', (ex + 4).toFixed(1));
  if (reduced) return seq;
  const S = Object.fromEntries(SHOTS.map((x) => [x.id, x.at])) as Record<ShotId, number>;

  // 1 · Slate: the board rises into frame, the stick opens wider (anticipation) and claps shut with a bounce.
  seq.add(q('[data-slate-board]'), [{ transform: 'translateY(115%)' }, { transform: 'translateY(-3%)', offset: 0.7 }, { transform: 'none' }], { at: S.slate + 80, duration: 760, easing: EASE.out });
  seq.add(q('[data-slate-stick]'), [
    { transform: 'rotate(0deg)' }, { transform: 'rotate(-24deg)', offset: 0.35 }, { transform: 'rotate(-31deg)', offset: 0.62 },
    { transform: 'rotate(0deg)', offset: 0.78 }, { transform: 'rotate(-4deg)', offset: 0.86 }, { transform: 'rotate(0deg)' },
  ], { at: S.slate + 300, duration: 1300, easing: 'linear' });
  seq.add(qa('[data-slate-tick]'), [{ opacity: 0, transform: 'scale(0.4)' }, { opacity: 1, transform: 'scale(1)', offset: 0.3 }, { opacity: 0, transform: 'scale(1.5)' }], { at: S.slate + 1320, duration: 420, easing: EASE.out, stagger: 30 });

  // 2 · Nothing stops dead: the words arrive lead-first, then the ball bounces in and lands as the full stop.
  seq.add(qa('[data-ball-word]'), [{ opacity: 0, transform: 'translateY(26px)' }, { opacity: 1, transform: 'none' }], { at: S.ball + 120, duration: 620, easing: EASE.out, stagger: 110 });
  if (ball) {
    const { frames, total } = ballKeys({ x: ex, y: ey }, R);
    seq.add(ball, frames.map((f) => ({ offset: f.t / total, transform: `translate(${f.x.toFixed(1)}px, ${f.y.toFixed(1)}px) rotate(${f.rot.toFixed(1)}deg) scale(${f.sx.toFixed(3)}, ${f.sy.toFixed(3)}) rotate(${(-f.rot).toFixed(1)}deg)` })), { at: S.ball + 700, duration: total * 1000, easing: 'linear' });
    seq.add(q('[data-ball-shadow]'), [{ opacity: 0 }, { opacity: 0.22 }], { at: S.ball + 700 + total * 1000 - 200, duration: 200, easing: 'linear' });
  }
  // 3 · Tidewater: the tide runs under a wordmark whose letters ride the swell.
  qa('[data-tide-line]').forEach((el, i) => seq.add(el, [{ transform: 'translateX(0px)' }, { transform: `translateX(${i % 2 ? 160 : -160}px)` }], { at: S.tide, duration: 3200, easing: 'linear' }));
  qa('[data-tide-letter]').forEach((el, i) => seq.add(el, [
    { opacity: 0, transform: 'translateY(60%)' }, { opacity: 1, transform: 'translateY(-8%)', offset: 0.3 },
    { opacity: 1, transform: 'translateY(6%)', offset: 0.62 }, { opacity: 1, transform: 'translateY(0%)' },
  ], { at: S.tide + 160 + i * 55, duration: 2400, easing: EASE.inOut }));

  // 4 · The Night Ferry: the beam crosses the sea, the title surfaces, the ferry drifts.
  seq.add(q('[data-ferry-beam]'), [{ transform: 'rotate(-16deg)' }, { transform: 'rotate(10deg)' }], { at: S.ferry, duration: 3200, easing: EASE.inOut });
  seq.add(q('[data-ferry-boat]'), [{ transform: 'translateX(-60px)' }, { transform: 'translateX(40px)' }], { at: S.ferry, duration: 3200, easing: 'linear' });
  seq.add(q('[data-ferry-title]'), [{ opacity: 0, transform: 'translateY(18px)' }, { opacity: 1, transform: 'none' }], { at: S.ferry + 700, duration: 1100, easing: EASE.enter });
  seq.add(q('[data-ferry-credit]'), [{ opacity: 0 }, { opacity: 1 }], { at: S.ferry + 1500, duration: 700, easing: 'linear' });

  // 5 · Halden Type: weight lands on the beat, width breathes between.
  seq.add(q('[data-type-glyph]'), [
    { fontWeight: 200, fontStretch: '100%' }, { fontWeight: 800, fontStretch: '100%', offset: 0.32 },
    { fontWeight: 800, fontStretch: '75%', offset: 0.6 }, { fontWeight: 500, fontStretch: '100%', offset: 0.86 }, { fontWeight: 600, fontStretch: '100%' },
  ], { at: S.type + 150, duration: 2700, easing: EASE.inOut });
  seq.add(q('[data-type-knob]'), [{ transform: 'translateX(0%)' }, { transform: 'translateX(100%)', offset: 0.32 }, { transform: 'translateX(100%)', offset: 0.6 }, { transform: 'translateX(50%)', offset: 0.86 }, { transform: 'translateX(66%)' }], { at: S.type + 150, duration: 2700, easing: EASE.inOut });

  // 6 · Crumb: the phone lands, then the rolls hop in turn (squash on landing, stretch on take-off).
  seq.add(q('[data-crumb-phone]'), [{ transform: 'translateY(70%)' }, { transform: 'translateY(-4%)', offset: 0.68 }, { transform: 'none' }], { at: S.crumb + 60, duration: 820, easing: EASE.out });
  qa('[data-crumb-roll]').forEach((el, i) => seq.add(el, [
    { transform: 'translateY(0) scale(1, 1)' }, { transform: 'translateY(0) scale(1.18, 0.82)', offset: 0.12 },
    { transform: 'translateY(-70%) scale(0.9, 1.12)', offset: 0.3 }, { transform: 'translateY(-96%) scale(1, 1)', offset: 0.45 },
    { transform: 'translateY(0) scale(1.24, 0.78)', offset: 0.72 }, { transform: 'translateY(0) scale(0.96, 1.04)', offset: 0.84 },
    { transform: 'translateY(0) scale(1, 1)' },
  ], { at: S.crumb + 760 + i * 260, duration: 900, easing: 'linear' }));

  // 7 · End card: "Lead" arrives, "Lag" lags behind it and overshoots further. Follow-through, as a logo.
  seq.add(q('[data-end-lead]'), [{ opacity: 0, transform: 'translateX(-40%)' }, { opacity: 1, transform: 'translateX(3%)', offset: 0.6 }, { opacity: 1, transform: 'none' }], { at: S.end + 80, duration: 700, easing: EASE.out });
  seq.add(q('[data-end-amp]'), [{ opacity: 0, transform: 'scale(0.4)' }, { opacity: 1, transform: 'scale(1.12)', offset: 0.6 }, { opacity: 1, transform: 'none' }], { at: S.end + 220, duration: 600, easing: EASE.out });
  seq.add(q('[data-end-lag]'), [{ opacity: 0, transform: 'translateX(-90%)' }, { opacity: 1, transform: 'translateX(9%)', offset: 0.55 }, { opacity: 1, transform: 'translateX(-2%)', offset: 0.8 }, { opacity: 1, transform: 'none' }], { at: S.end + 300, duration: 1000, easing: EASE.out });
  seq.add(q('[data-end-mail]'), [{ opacity: 0 }, { opacity: 1 }], { at: S.end + 1100, duration: 600, easing: 'linear' });
  return seq;
}

export function Reel({ onPlaying }: { onPlaying: (playing: boolean) => void }) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const screen = useRef<HTMLDivElement>(null);
  const seq = useRef<Sequence | null>(null);
  const tc = useRef<Text | null>(null);
  const range = useRef<HTMLInputElement>(null);
  const shotName = useRef<HTMLSpanElement>(null);
  const [playing, setPlaying] = useState(false);
  const [started, setStarted] = useState(false);
  const [said, setSaid] = useState('');
  const resumeAfterScrub = useRef(false);
  const onPlayingRef = useRef(onPlaying);
  onPlayingRef.current = onPlaying;

  /** Timecode, scrubber and shot name from the sequence clock (DOM writes, no render). */
  const paint = useCallback((ms?: number) => {
    const t = ms ?? (seq.current ? seq.current.progress * REEL_MS : 0);
    if (tc.current) tc.current.nodeValue = timecode(t);
    const r = range.current;
    if (r) {
      r.value = String(Math.round(t));
      r.setAttribute('aria-valuetext', `${timecode(t).slice(0, 5)} of ${timecode(REEL_MS).slice(0, 5)}, ${shotAt(t).label}`);
    }
    const label = shotAt(t).label;
    if (shotName.current && shotName.current.textContent !== label) shotName.current.textContent = label;
  }, []);

  /** The timeline is built on first use (fonts are in by then), and again when reduced motion changes. */
  const reducedRef = useRef(reduced);
  reducedRef.current = reduced;
  const ensure = useCallback((): Sequence | null => {
    if (!seq.current && screen.current) seq.current = build(screen.current, reducedRef.current);
    return seq.current;
  }, []);
  const firstReduced = useRef(reduced);
  useEffect(() => {
    if (firstReduced.current === reduced) return;
    firstReduced.current = reduced;
    const prev = seq.current;
    if (!prev) return;
    const at = prev.progress;
    prev.cancel();
    seq.current = null;
    setPlaying(false);
    ensure()?.seek(at);
  }, [reduced, ensure]);
  useEffect(() => () => { seq.current?.cancel(); seq.current = null; }, []);

  useEffect(() => { onPlayingRef.current(playing); }, [playing]);
  useEffect(() => () => onPlayingRef.current(false), []);

  useRafLoop(screen, () => paint(), playing);

  const play = () => {
    const sq = ensure();
    if (!sq) return;
    setStarted(true);
    setPlaying(true);
    setSaid('Reel playing.');
    sq.play().then((finished) => {
      if (!finished || seq.current !== sq) return;
      setPlaying(false);
      setSaid('Reel finished.');
      paint(REEL_MS);
    });
  };
  const pause = () => {
    seq.current?.pause();
    setPlaying(false);
    setSaid('Reel paused.');
    paint();
  };
  const toggle = (on: boolean) => (on ? play() : pause());

  const scrubTo = (ms: number) => {
    const sq = ensure();
    if (!sq) return;
    setStarted(true);
    sq.seek(ms / REEL_MS);
    paint(ms);
    if (playing) setPlaying(false);
  };

  const ends = SHOTS.map((x) => x.at);
  return (
    <div className={s.reel}>
      <div
        ref={screen}
        className={s.screen}
        data-lit=""
        data-started={started || undefined}
        onClick={() => toggle(!playing)}
        aria-hidden="true"
      >
        <div className={s.shot} data-shot="slate">
          <div className={s.slateBoard} data-slate-board="">
            <div className={s.slateStick} data-slate-stick="">{Array.from({ length: 9 }, (_, i) => <span key={i} />)}</div>
            <div className={s.slateBody}>
              <p><span>Prod.</span>Reel 2026</p>
              <p><span>Studio</span>{STUDIO.name}</p>
              <p><span>Scene</span>01</p><p><span>Take</span>03</p>
            </div>
            <i className={s.slateTick} data-slate-tick="" style={{ '--a': '-30deg' } as CSSProperties} />
            <i className={s.slateTick} data-slate-tick="" style={{ '--a': '-60deg' } as CSSProperties} />
            <i className={s.slateTick} data-slate-tick="" style={{ '--a': '-90deg' } as CSSProperties} />
          </div>
        </div>

        <div className={s.shot} data-shot="ball">
          <svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid meet" className={s.ballSvg} focusable="false">
            <text x="200" y="560" className={s.ballText} data-ball-line="">
              <tspan data-ball-word="" className={s.ballDisplay}>Nothing</tspan>
              <tspan data-ball-word="" className={s.ballSerif} dx="30">stops</tspan>
              <tspan data-ball-word="" className={s.ballDisplay} dx="30">dead</tspan>
            </text>
            <ellipse data-ball-shadow="" className={s.ballShadow} cx="1356" cy="563" rx="25" ry="5" />
            <g data-ball="" className={s.ballBody} style={{ transform: 'translate(1352px, 538px)' }}>
              <circle r="22" />
            </g>
          </svg>
          <p className={s.shotCap}>Bounce timed by hand · squash on every contact</p>
        </div>

        <div className={s.shot} data-shot="tide">
          <svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice" className={s.tideSvg} focusable="false">
            {[0, 1, 2, 3, 4, 5, 6, 7].map((i) => (
              <path key={i} data-tide-line="" d={(() => { let d = `M-480 ${560 + i * 40}`; for (let x = -480; x < 2080; x += 160) d += ` q40 ${-(10 + i * 3)} 80 0 t80 0`; return d; })()} strokeWidth={2 + i * 0.5} opacity={0.3 + i * 0.08} />
            ))}
          </svg>
          <p className={s.tideMark}>{'TIDEWATER'.split('').map((l, i) => <span key={i} data-tide-letter="" style={{ '--y': `${(Math.sin(i * 0.78) * 0.09).toFixed(3)}em` } as CSSProperties}>{l}</span>)}</p>
          <p className={s.shotCap} data-top="">Tidewater Institute · living identity · 2025</p>
        </div>

        <div className={s.shot} data-shot="ferry">
          <svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice" className={s.ferrySvg} focusable="false">
            <defs>
              <linearGradient id={`${uid}beam`} x1="1" y1="0" x2="0" y2="0">
                <stop offset="0" stopColor="#ffe2a0" stopOpacity="0.7" />
                <stop offset="1" stopColor="#ffe2a0" stopOpacity="0" />
              </linearGradient>
            </defs>
            <rect y="610" width="1600" height="290" fill="#070b1f" />
            <g data-ferry-beam="" style={{ transformOrigin: '1290px 330px' }}><path d="M1290 330 L120 170 L120 500 Z" fill={`url(#${uid}beam)`} /></g>
            <path d="M1262 610 L1274 350 h32 L1318 610Z" fill="#d9d4ea" />
            <path d="M1266 520h48v26h-50zM1270 430h40v26h-41z" fill="#b8213a" />
            <rect x="1272" y="306" width="36" height="44" rx="6" fill="#ffe29a" />
            <g data-ferry-boat=""><path d="M330 610h330l-34 38H364z" fill="#03050f" /><rect x="410" y="570" width="180" height="40" rx="5" fill="#03050f" /><g fill="#ffcf6b">{[426, 452, 478, 504, 530, 556].map((x) => <rect key={x} x={x} y="582" width="13" height="10" rx="2" />)}</g></g>
          </svg>
          <p className={s.ferryTitle} data-ferry-title="">The Night Ferry</p>
          <p className={s.ferryCredit} data-ferry-credit="">main titles · sample</p>
        </div>

        <div className={s.shot} data-shot="type">
          <span className={s.typeGlyph} data-type-glyph="">Rg</span>
          <span className={s.typeAxis}><span>wght</span><span className={s.typeTrack}><span className={s.typeKnob} data-type-knob="" /></span><span>wdth</span></span>
          <p className={s.shotCap}>Halden Type · variable specimen · 2024</p>
        </div>

        <div className={s.shot} data-shot="crumb">
          <div className={s.crumbPhone} data-crumb-phone=""><span className={s.crumbLoaf} /><span className={s.crumbWord}>Crumb</span><span className={s.crumbDots}><i /><i /><i /></span></div>
          <div className={s.crumbShelf}>{[0, 1, 2].map((i) => <span key={i} className={s.crumbRoll} data-crumb-roll="" />)}</div>
          <p className={s.shotCap}>Crumb · onboarding · 2023</p>
        </div>

        <div className={s.shot} data-shot="end">
          <p className={s.endMark}>
            <span data-end-lead="">Lead</span>
            <span data-end-amp="" className={s.endAmp}>&amp;</span>
            <span data-end-lag="">Lag</span>
          </p>
          <p className={s.endMail} data-end-mail="">{STUDIO.email} · a fictional studio</p>
        </div>

        <div className={s.poster}>
          <p className={s.posterKicker}>Reel 2026 <span>·</span> sample</p>
          <p className={s.posterTitle}>Twenty seconds<br />of follow-through.</p>
          <p className={s.posterHint}>Press play. Birb has been waiting.</p>
        </div>
        <span className={s.vignette} />
        {/* Keyed, so the cursor follower meets a new element (and reads the new label) when the state flips. */}
        <span key={playing ? 'pause' : 'play'} className={s.hit} data-cursor-label={playing ? 'Pause' : 'Play'} />
      </div>

      <div className={s.transport}>
        <span className={s.playWrap} data-cursor="magnet">
          <LottieIcon
            animationData={PLAY}
            segments={ICONS.play.segments}
            grid={24}
            size={40}
            label="Play reel"
            pressed={playing}
            onToggle={toggle}
            className={s.playButton}
          />
        </span>
        <span className={s.timecode} aria-hidden="true"><span ref={(el) => { if (el && !tc.current) { tc.current = document.createTextNode(timecode(0)); el.appendChild(tc.current); } }} /><span className={s.tcTotal}> / {timecode(REEL_MS)}</span></span>
        <div className={s.scrub}>
          <input
            ref={range}
            className={s.range}
            type="range"
            min={0}
            max={REEL_MS}
            step={Math.round(1000 / FPS)}
            defaultValue={0}
            aria-label="Reel position"
            aria-valuetext={`00:00 of ${timecode(REEL_MS).slice(0, 5)}, ${SHOTS[0].label}`}
            onPointerDown={() => { resumeAfterScrub.current = playing; if (playing) pause(); }}
            onPointerUp={() => { if (resumeAfterScrub.current) { resumeAfterScrub.current = false; play(); } }}
            onInput={(e) => scrubTo(Number((e.target as HTMLInputElement).value))}
          />
          <span className={s.marks} aria-hidden="true">{ends.map((t) => <i key={t} style={{ left: `${(t / REEL_MS) * 100}%` }} />)}</span>
        </div>
        <span className={s.shotName} aria-hidden="true"><span ref={shotName}>{SHOTS[0].label}</span></span>
      </div>
      <p className={s.srOnly} role="status">{said}</p>
    </div>
  );
}

/* The screening room: a reel on a screen that lights the room, Birb in a pool of light beside it, and the rating band.
   The room inherits the dark tokens its section sets; the rating sits in the page palette. */

.srOnly {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap; border: 0;
}

/* ── Reel ───────────────────────────────────────────────────────────────────────────────────────────────── */
.reel { display: grid; gap: 14px; min-width: 0; }
.screen {
  position: relative;
  isolation: isolate;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: 14px;
  background: #050504;
  container-type: inline-size;
  cursor: pointer;
  box-shadow:
    0 0 0 1px #ffffff17,
    calc(var(--lx) * -3px) calc(var(--ly) * -3px) 6px rgb(0 0 0 / 0.6),
    calc(var(--lx) * -26px) calc(var(--ly) * -30px) 70px -24px rgb(0 0 0 / 0.9),
    0 0 140px -50px rgb(255 190 130 / 0.35);
  user-select: none;
  -webkit-user-select: none;
}
.shot { position: absolute; inset: 0; opacity: 0; overflow: hidden; }
.shotCap {
  position: absolute;
  left: 4cqi;
  bottom: 3.4cqi;
  margin: 0;
  font-family: var(--mk-font-mono);
  font-size: max(9px, 1.45cqi);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #f1ebdebf;
}
.shotCap[data-top] { top: 3.4cqi; bottom: auto; }
.hit { position: absolute; inset: 0; z-index: 7; }
.vignette {
  position: absolute;
  inset: 0;
  z-index: 6;
  border-radius: inherit;
  background: radial-gradient(130% 110% at 50% 46%, transparent 58%, rgb(0 0 0 / 0.42));
  pointer-events: none;
}
.poster {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: grid;
  align-content: end;
  gap: 1.4cqi;
  padding: 5cqi 5.4cqi;
  background:
    radial-gradient(60% 80% at 78% 30%, #ff6a3d33, transparent 70%),
    radial-gradient(80% 90% at 20% 100%, #f1ebde14, transparent 70%),
    #0e0d0b;
  color: #f1ebde;
  transition: opacity var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, ease), visibility 0s linear var(--mk-duration-moderate, 360ms);
}
.screen[data-started] .poster { opacity: 0; visibility: hidden; }
.posterKicker { margin: 0; font-family: var(--mk-font-mono); font-size: max(10px, 1.5cqi); letter-spacing: 0.14em; text-transform: uppercase; color: #ff8a5f; }
.posterKicker span { color: #f1ebde80; }
.posterTitle { margin: 0; font-family: var(--mk-font-display); font-size: 7.4cqi; font-weight: 780; line-height: 0.92; letter-spacing: -0.045em; }
.posterHint { margin: 0; font-size: max(12px, 1.9cqi); color: #f1ebdeb3; }

/* 1 · Slate */
.shot[data-shot='slate'] { display: grid; place-items: center; background: radial-gradient(70% 80% at 50% 42%, #2b2720, #0f0e0c 78%); }
.slateBoard { position: relative; width: 52cqi; margin-top: 5cqi; filter: drop-shadow(0 2cqi 3cqi rgb(0 0 0 / 0.55)); }
.slateStick {
  display: flex;
  height: 5cqi;
  overflow: hidden;
  border-radius: 0.6cqi 0.6cqi 0 0;
  background: #f1ebde;
  transform-origin: 0.6cqi 100%;
}
.slateStick span { flex: 1; transform: skewX(-38deg) scaleX(1.25); }
.slateStick span:nth-child(odd) { background: #16140f; }
.slateBody {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.6cqi 3cqi;
  padding: 2.8cqi 3.2cqi;
  border: 0.35cqi solid #f1ebde;
  border-top-width: 0.6cqi;
  background: #171612;
  color: #f1ebde;
}
.slateBody p { display: grid; gap: 0.4cqi; margin: 0; font-family: var(--mk-font-display); font-size: 3.4cqi; font-weight: 720; letter-spacing: -0.02em; line-height: 1; }
.slateBody p:nth-child(-n + 2) { grid-column: 1 / -1; }
.slateBody span { font-family: var(--mk-font-mono); font-size: 1.3cqi; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; color: #f1ebde99; }
.slateTick { position: absolute; left: -1cqi; top: 4.6cqi; width: 4.4cqi; height: 0.42cqi; border-radius: 1cqi; background: #ff6a3d; opacity: 0; transform-origin: 100% 50%; rotate: var(--a); translate: -100% 0; }

/* 2 · Nothing stops dead */
.shot[data-shot='ball'] { background: radial-gradient(90% 90% at 40% 45%, #fbf7ee, #ebe4d4); }
.ballSvg { position: absolute; inset: 0; width: 100%; height: 100%; }
.ballText { font-size: 168px; fill: #17150f; }
.ballDisplay { font-family: var(--mk-font-display); font-weight: 800; letter-spacing: -0.04em; }
.ballSerif { font-family: var(--mk-font-serif); font-style: italic; font-weight: 400; font-size: 1.16em; }
.ballBody circle { fill: #bf2f09; }
.ballShadow { fill: #17150f; opacity: 0.22; }
.shot[data-shot='ball'] .shotCap { color: #59564d; }

/* 3 · Tidewater */
.shot[data-shot='tide'] { background: linear-gradient(#0a2731, #11505b 62%, #0c3a45); }
.tideSvg { position: absolute; inset: 0; width: 100%; height: 100%; fill: none; stroke: #7fd6c8; stroke-linecap: round; }
.tideMark {
  position: absolute;
  left: 0;
  right: 0;
  top: 22%;
  display: flex;
  justify-content: center;
  margin: 0;
  font-family: var(--mk-font-display);
  font-size: 13.5cqi;
  font-stretch: 75%;
  font-weight: 800;
  letter-spacing: 0.01em;
  line-height: 1;
  color: #f3ecda;
}
.tideMark span { display: inline-block; translate: 0 var(--y, 0); }

/* 4 · The Night Ferry */
.shot[data-shot='ferry'] { background: linear-gradient(#060a1b, #1b2350 72%, #2a2c5c); }
.ferrySvg { position: absolute; inset: 0; width: 100%; height: 100%; }
.ferryTitle { position: absolute; left: 0; right: 0; top: 17%; margin: 0; text-align: center; font-family: var(--mk-font-serif); font-style: italic; font-size: 9cqi; line-height: 1; color: #f4ecd8; text-shadow: 0 0.4cqi 3cqi rgb(0 0 0 / 0.6); }
.ferryCredit { position: absolute; left: 0; right: 0; top: 31%; margin: 0; text-align: center; font-family: var(--mk-font-mono); font-size: max(9px, 1.5cqi); letter-spacing: 0.24em; text-transform: uppercase; color: #f4ecd8b3; }

/* 5 · Halden Type */
.shot[data-shot='type'] { background: #efe8d8; }
.typeGlyph {
  position: absolute;
  left: 0;
  right: 0;
  top: 8%;
  text-align: center;
  font-family: var(--mk-font-display);
  font-size: 34cqi;
  font-weight: 600;
  font-stretch: 100%;
  line-height: 1;
  letter-spacing: -0.04em;
  color: #17150f;
}
.typeAxis { position: absolute; left: 22%; right: 22%; bottom: 13%; display: flex; align-items: center; gap: 2cqi; font-family: var(--mk-font-mono); font-size: max(9px, 1.4cqi); letter-spacing: 0.08em; text-transform: uppercase; color: #3d382d; }
.typeTrack { position: relative; flex: 1; height: 0.3cqi; min-height: 2px; background: #17150f33; }
.typeKnob { position: absolute; inset: -1.1cqi auto auto 0; display: block; width: 100%; height: 0; transform: translateX(66%); }
.typeKnob::before { content: ''; position: absolute; left: -1.1cqi; top: 0; width: 2.2cqi; height: 2.2cqi; border-radius: 50%; background: #bf2f09; }
.shot[data-shot='type'] .shotCap { color: #59564d; }

/* 6 · Crumb */
.shot[data-shot='crumb'] { background: linear-gradient(135deg, #f6c66c, #ec8f3a); }
.crumbPhone {
  position: absolute;
  left: 50%;
  top: 9%;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 2.4cqi;
  width: 20cqi;
  height: 39cqi;
  margin-left: -10cqi;
  border: 1cqi solid #fff8ee;
  border-radius: 3.4cqi;
  background: #fdebd2;
  box-shadow: 0 3cqi 5cqi -2cqi rgb(90 40 0 / 0.45);
}
.crumbLoaf { width: 11cqi; aspect-ratio: 1.45; border-radius: 50%; background: radial-gradient(70% 60% at 40% 32%, #f0b86a, #c8742f 70%, #9c5520); }
.crumbWord { font-family: var(--mk-font-display); font-size: 3.6cqi; font-weight: 800; letter-spacing: -0.03em; color: #5a2d0c; }
.crumbDots { display: flex; gap: 0.9cqi; }
.crumbDots i { width: 0.9cqi; height: 0.9cqi; border-radius: 50%; background: #5a2d0c; opacity: 0.3; }
.crumbDots i:first-child { opacity: 1; }
.crumbShelf { position: absolute; right: 9%; bottom: 20%; display: flex; gap: 1.6cqi; align-items: flex-end; }
.crumbRoll { width: 6.4cqi; aspect-ratio: 1.35; border-radius: 50% 50% 44% 44%; background: radial-gradient(70% 60% at 40% 32%, #f3c27a, #c8742f 70%, #9c5520); box-shadow: 0 1cqi 1cqi -0.6cqi rgb(70 30 0 / 0.5); transform-origin: 50% 100%; }
.shot[data-shot='crumb'] .shotCap { color: #4a2508; }

/* 7 · End card */
.shot[data-shot='end'] { display: grid; place-content: center; justify-items: center; gap: 2.4cqi; background: radial-gradient(70% 80% at 50% 45%, #1c1914, #0b0a08); }
.endMark { display: flex; align-items: baseline; gap: 1.6cqi; margin: 0; font-family: var(--mk-font-display); font-size: 14cqi; font-weight: 800; letter-spacing: -0.045em; line-height: 1; color: #f1ebde; }
.endMark span { display: inline-block; }
.endAmp { font-family: var(--mk-font-serif); font-style: italic; font-weight: 400; color: #ff6a3d; }
.endMail { margin: 0; font-family: var(--mk-font-mono); font-size: max(10px, 1.6cqi); letter-spacing: 0.08em; color: #f1ebdeb3; }

/* Transport */
.transport {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 4px 16px;
}
.playWrap { display: inline-grid; border-radius: 50%; }
.playButton {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  --lmi-solid: var(--mk-signal);
  --lmi-on: var(--mk-on-signal);
}
.playButton > span:first-child {
  filter: drop-shadow(calc(var(--lx) * -1px) calc(var(--ly) * -1px) 1px rgb(0 0 0 / 0.4)) drop-shadow(calc(var(--lx) * -6px) calc(var(--ly) * -7px) 9px rgb(0 0 0 / 0.45));
  transition: transform var(--ll-pop-ms, 400ms) var(--ll-pop, ease);
}
.playButton:active > span:first-child { transform: scale(0.92); transition-duration: var(--mk-duration-instant, 90ms); }
.timecode { font-family: var(--mk-font-mono); font-size: 0.875rem; font-variant-numeric: tabular-nums; letter-spacing: 0.02em; white-space: nowrap; }
.tcTotal { color: var(--mk-ink-muted); }
.scrub { position: relative; min-width: 0; }
.range {
  width: 100%;
  height: 44px;
  margin: 0;
  background: transparent;
  accent-color: var(--mk-signal);
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
}
.range::-webkit-slider-runnable-track { height: 3px; border-radius: 3px; background: var(--mk-line); }
.range::-moz-range-track { height: 3px; border-radius: 3px; background: var(--mk-line); }
.range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  margin-top: -7.5px;
  border-radius: 50%;
  border: 0;
  background: var(--mk-signal);
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--mk-signal) 22%, transparent), calc(var(--lx) * -2px) calc(var(--ly) * -2px) 4px rgb(0 0 0 / 0.4);
}
.range::-moz-range-thumb { width: 18px; height: 18px; border-radius: 50%; border: 0; background: var(--mk-signal); }
.range:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 2px; border-radius: 6px; }
.marks { position: absolute; left: 9px; right: 9px; top: 50%; height: 0; pointer-events: none; }
.marks i { position: absolute; top: -6px; width: 1px; height: 12px; background: var(--mk-ink-muted); opacity: 0.6; }
.marks i:first-child { display: none; }
.shotName { font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--mk-ink-muted); white-space: nowrap; }
@container (max-width: 640px) {
  .transport { grid-template-columns: auto minmax(0, 1fr); }
  .timecode { justify-self: end; }
  .scrub { grid-column: 1 / -1; grid-row: 2; }
  .shotName { display: none; }
}

/* ── Mascot ─────────────────────────────────────────────────────────────────────────────────────────────── */
.mascot { display: grid; gap: 12px; margin: 0; min-width: 0; }
/* Under the screen (one column): Birb's stage beside its caption on tablets, a shorter stage on phones. */
@container (min-width: 600px) and (max-width: 979px) {
  .mascot { grid-template-columns: minmax(0, 340px) minmax(0, 1fr); align-items: end; column-gap: 22px; }
  .mascotCap { flex-direction: column; align-items: flex-start; }
}
@container (max-width: 599px) { .mascotStage { max-height: 420px; } }
.mascotStage {
  position: relative;
  isolation: isolate;
  aspect-ratio: 1 / 1.08;
  max-height: 560px;
  overflow: hidden;
  border-radius: 18px;
  background:
    radial-gradient(70% 55% at 30% 0%, rgb(255 190 130 / 0.16), transparent 70%),
    radial-gradient(60% 50% at 50% 34%, #27231c, #100f0c 78%);
  box-shadow:
    inset 0 0 0 1px #ffffff12,
    calc(var(--lx) * -3px) calc(var(--ly) * -3px) 6px rgb(0 0 0 / 0.5),
    calc(var(--lx) * -20px) calc(var(--ly) * -24px) 60px -26px rgb(0 0 0 / 0.85);
}
.mascotPool { position: absolute; left: 6%; right: 6%; bottom: 1%; height: 26%; z-index: -1; background: radial-gradient(closest-side, rgb(255 236 205 / 0.2), transparent); }
.mascotBox { position: absolute; left: 50%; bottom: 3%; height: 88%; aspect-ratio: 1; max-width: 100%; translate: -50% 0; }
.fill { width: 100%; height: 100%; }
.mascotWaiting { position: absolute; inset: 0; display: grid; place-items: end center; }
.mascotNote { align-self: end; margin: 0 16px 16%; font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.06em; text-align: center; color: var(--mk-ink-muted); }
.roundButton {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--mk-line);
  border-radius: 50%;
  background: color-mix(in oklab, var(--mk-surface) 82%, transparent);
  color: var(--mk-ink);
  cursor: pointer;
  transition: scale var(--ll-pop-ms, 400ms) var(--ll-pop, ease), background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.roundButton:hover { background: var(--mk-surface-2); }
.roundButton:active { scale: 0.92; transition-duration: var(--mk-duration-instant, 90ms); }
.roundButton:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 2px; }
.mascotCap { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; }
.mascotName { display: inline-flex; align-items: center; gap: 12px; font-family: var(--mk-font-display); font-size: 1.375rem; font-weight: 740; letter-spacing: -0.03em; }
.mascotState { display: inline-flex; align-items: center; gap: 7px; font-family: var(--mk-font-mono); font-size: 0.6875rem; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted); }
.mascotState i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; opacity: 0.5; }
.mascotState i[data-live] { opacity: 1; background: var(--mk-signal); box-shadow: 0 0 0 3px color-mix(in oklab, var(--mk-signal) 24%, transparent); }
.mascotControls { display: inline-flex; flex-wrap: wrap; gap: 8px; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 16px 0 13px;
  border: 1px solid var(--mk-line-strong);
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink);
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 620;
  cursor: pointer;
  transition: scale var(--ll-pop-ms, 400ms) var(--ll-pop, ease), background-color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease), color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
}
.chip:hover { background: color-mix(in oklab, var(--mk-ink) 8%, transparent); }
.chip:active { scale: 0.95; transition-duration: var(--mk-duration-instant, 90ms); }
.chip:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 3px; }
.chip[aria-pressed='true'] { background: var(--mk-ink); color: var(--mk-bg); }
.eq { display: inline-flex; align-items: flex-end; gap: 2px; width: 14px; height: 14px; }
.eq i { width: 3px; height: 100%; border-radius: 1px; background: currentColor; transform: scaleY(0.4); transform-origin: 50% 100%; }
.eq i:nth-child(2) { transform: scaleY(0.75); }
.eq i:nth-child(3) { transform: scaleY(0.55); }

/* ── Rating ─────────────────────────────────────────────────────────────────────────────────────────────── */
.rating { display: grid; gap: 16px; min-width: 0; }
.fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.legend { display: block; margin: 0 0 14px; padding: 0; font-family: var(--mk-font-display); font-size: clamp(1.5rem, 3cqi, 2rem); font-weight: 720; letter-spacing: -0.03em; line-height: 1.05; }
.band {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  aspect-ratio: 500 / 170;
  border-radius: var(--mk-radius-l, 18px);
  background: var(--mk-signal);
  box-shadow:
    calc(var(--lx) * -1.5px) calc(var(--ly) * -1.5px) 2px rgb(var(--ll-shadow) / calc(0.2 * var(--ll-shadow-a))),
    calc(var(--lx) * -18px) calc(var(--ly) * -22px) 44px -18px color-mix(in oklab, var(--mk-signal) 70%, transparent);
}
.band::after { content: ''; position: absolute; inset: 0; z-index: 3; border-radius: inherit; box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.1), inset 0 1px 0 rgb(255 255 255 / 0.3); pointer-events: none; }
/* The artwork's own gradient (sampled), cropped like the canvas; lights and darks kept, hue from the signal token. */
.bandArt { position: absolute; inset: 0; background: linear-gradient(135deg, #ff2fd3, #ff003f) 50% 50% / 100% 294.12%; transition: opacity var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, ease); }
.band[data-ready] .bandArt { opacity: 0; }
.bandStar {
  position: absolute;
  top: 47.06%;
  left: calc(15% + (var(--at, 1) - 0.5) * 14%);
  width: 10.4%;
  translate: -50% -50%;
  fill: #6e0228;
  stroke: #c3157e;
  stroke-width: 1.4;
  stroke-linejoin: round;
}
.bandStar[data-on] { fill: #fff8fb; }
.bandCanvas, .ghost { position: absolute; inset: 0; width: 100%; height: 100%; }
.ghost { opacity: 0; pointer-events: none; }
.band[data-failed] .bandCanvas { display: none; }
.band :is(.bandArt, .bandCanvas, .ghost) { mix-blend-mode: luminosity; }
.burst {
  position: absolute;
  top: 47.06%;
  left: calc(15% + (var(--at, 1) - 0.5) * 14%);
  z-index: 1;
  width: 12%;
  aspect-ratio: 1;
  border: 2px solid rgb(255 255 255 / 0.95);
  border-radius: 50%;
  opacity: 0;
  transform: translate(-50%, -50%);
  pointer-events: none;
}
.slots { position: absolute; inset: 0 15%; z-index: 2; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); touch-action: pan-y; }
.slot { position: relative; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.radio { position: absolute; top: 47%; left: 50%; width: 1px; height: 1px; margin: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; appearance: none; }
.ring { position: absolute; top: 47.06%; left: 50%; width: 84%; aspect-ratio: 1; border-radius: 50%; translate: -50% -50%; pointer-events: none; }
.radio:focus-visible + .ring { box-shadow: 0 0 0 2px #fff, 0 0 0 4px var(--mk-focus); }
.verdict { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 4px 16px; min-width: 0; }
.score { display: inline-flex; align-items: baseline; gap: 0.3rem; margin: 0; overflow: hidden; font-family: var(--mk-font-display); font-weight: 760; line-height: 1; letter-spacing: -0.04em; }
.scoreNum { display: inline-block; min-width: 0.62em; font-size: clamp(2.5rem, 5cqi, 3.25rem); font-variant-numeric: tabular-nums; text-align: center; }
.scoreOf { font-size: 1rem; letter-spacing: 0; color: var(--mk-ink-muted); }
.score[data-preview] .scoreNum, .score[data-empty] .scoreNum { color: var(--mk-ink-muted); }
.score[data-empty] .scoreNum { font-weight: 300; }
.word { min-width: 0; margin: 0; font-size: 1.0625rem; font-weight: 600; line-height: 1.3; }
.tag { display: inline-block; margin-right: 0.5rem; padding: 0.125rem 0.375rem; border: 1px solid var(--mk-line-strong); border-radius: var(--mk-radius-s, 4px); font-family: var(--mk-font-mono); font-size: 0.625rem; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; vertical-align: 0.12em; }
.textButton {
  min-height: 44px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink);
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, var(--mk-ink) 40%, transparent);
  text-underline-offset: 0.25em;
  cursor: pointer;
}
.textButton:hover { background: color-mix(in oklab, var(--mk-ink) 6%, transparent); }
.textButton:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 2px; }
.textButton[aria-disabled='true'] { cursor: default; color: var(--mk-ink-muted); text-decoration-color: transparent; background: transparent; }
.ratingNote { margin: 0; font-size: 0.875rem; line-height: 1.5; color: var(--mk-ink-muted); }

@media (prefers-reduced-motion: no-preference) {
  :global([data-palette]:not([data-reduced])) .scoreNum { animation: ll-tick var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease) both; }
  :global([data-palette]:not([data-reduced])) .eq[data-on] i { animation: ll-eq var(--mk-duration-moderate, 360ms) var(--mk-ease-inOut, ease-in-out) infinite alternate; }
  :global([data-palette]:not([data-reduced])) .eq[data-on] i:nth-child(2) { animation-delay: calc(var(--mk-duration-moderate, 360ms) * -0.66); }
  :global([data-palette]:not([data-reduced])) .eq[data-on] i:nth-child(3) { animation-delay: calc(var(--mk-duration-moderate, 360ms) * -0.33); }
}
@keyframes ll-tick { from { opacity: 0; transform: translateY(42%); } }
@keyframes ll-eq { from { transform: scaleY(0.3); } to { transform: scaleY(1); } }
:global([data-reduced]) :is(.chip, .roundButton):active { scale: none; }

/* Lead & Lag — a light table in a studio. Paper, ink and one signal colour; the night palette is a darkroom with a
   safelight. One lamp: --lx / --ly point from an element toward it (upper left at rest, carried by the pointer on fine
   pointers); every shadow falls away from it, every highlight faces it. Elevation is two shadows: a tight contact one
   that shrinks as a thing lifts and a soft one that lengthens. */

.root {
  --ll-pad: clamp(16px, 3.4cqi, 44px);
  --lx: -0.473;
  --ly: -0.63;
  --ll-shadow: 17 15 10;
  position: relative;
  min-height: 100dvh;
  overflow-x: clip;
  background: var(--mk-bg);
  color: var(--mk-ink);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  -webkit-font-smoothing: antialiased;
}
.root[data-palette='day'] {
  --mk-bg: #f1ede4; --mk-surface: #fbf9f4; --mk-surface-2: #e8e3d7; --mk-ink: #13120f; --mk-ink-muted: #59564d;
  --mk-line: #13120f24; --mk-line-strong: #13120f; --mk-signal: #bf2f09; --mk-on-signal: #ffffff; --mk-focus: #1d4ed8;
  --mk-accent: var(--mk-signal);
  --ll-shadow-a: 1;
  --ll-band-edge: transparent;
  color-scheme: light;
}
.root[data-palette='night'] {
  --mk-bg: #0d0c0a; --mk-surface: #171613; --mk-surface-2: #22201c; --mk-ink: #f2eee5; --mk-ink-muted: #aaa69b;
  --mk-line: #f2eee526; --mk-line-strong: #f2eee5; --mk-signal: #ff5a2b; --mk-on-signal: #11110f; --mk-focus: #8ab4ff;
  --mk-accent: var(--mk-signal);
  --ll-shadow: 0 0 0;
  --ll-shadow-a: 2.1;
  --ll-band-edge: #f2eee51f;
  color-scheme: dark;
}
.root *, .root *::before, .root *::after { box-sizing: border-box; }
.srOnly {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap; border: 0;
}

/* ── Header ──────────────────────────────────────────────────────────────────────────────────────────────── */
.header {
  position: sticky;
  top: 44px;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 14px;
  height: 60px;
  padding: 0 var(--ll-pad);
  background: var(--mk-bg);
  border-bottom: 1px solid var(--mk-line);
}
.brand {
  display: inline-flex;
  align-items: baseline;
  gap: 0.12em;
  min-height: 44px;
  align-self: center;
  padding-top: 9px;
  font-family: var(--mk-font-display);
  font-size: 1.375rem;
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1;
  color: var(--mk-ink);
  text-decoration: none;
  white-space: nowrap;
}
.brandAmp { font-family: var(--mk-font-serif); font-style: italic; font-weight: 400; font-size: 1.18em; color: var(--mk-signal); }
.brandLag { position: relative; isolation: isolate; display: inline-block; }
/* Onion-skin ghosts: scroll speed makes "Lag" lag (written as --lag by a loop that sleeps at rest). Generated
   content with empty alternative text: decoration only, never read out. */
.brandLag::before,
.brandLag::after {
  content: 'Lag' / '';
  position: absolute;
  left: 0;
  top: 0;
  z-index: -1;
  color: var(--mk-signal);
  opacity: calc(var(--lag, 0) * 0.55);
  transform: translateX(calc(var(--lag, 0) * -0.3em));
  pointer-events: none;
}
.brandLag::after { opacity: calc(var(--lag, 0) * 0.28); transform: translateX(calc(var(--lag, 0) * -0.6em)); }
.tag {
  padding: 4px 9px;
  border: 1px solid var(--mk-line);
  border-radius: 999px;
  font-family: var(--mk-font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mk-ink-muted);
  white-space: nowrap;
}
.nav { margin-left: auto; }
.navList { display: flex; gap: 2px; margin: 0; padding: 0; list-style: none; }
.navLink {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0 12px;
  font-size: 0.875rem;
  font-weight: 550;
  text-decoration: none;
  color: var(--mk-ink);
}
.navLink::after {
  content: '';
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 11px;
  height: 1.5px;
  background: var(--mk-signal);
  transform: scaleX(0);
  transform-origin: 100% 50%;
  transition: transform var(--mk-duration-base, 240ms) var(--mk-ease-exit, ease);
}
.navLink:hover::after { transform: scaleX(1); transform-origin: 0 50%; transition: transform var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease); }
.headerEnd { display: inline-flex; align-items: center; gap: 2px; }
.iconWrap, .menuWrap { display: inline-grid; border-radius: 50%; }
.menuWrap { display: none; }
.iconButton {
  width: 44px;
  height: 44px;
  border-radius: 50%;
