}
@media (hover: hover) { .iconButton:hover { box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mk-ink) 26%, transparent); } }
.menu {
  position: absolute;
  top: 100%;
  right: var(--ll-pad);
  left: var(--ll-pad);
  padding: 8px;
  border: 1px solid var(--mk-line);
  border-radius: var(--mk-radius-l, 18px);
  background: var(--mk-surface);
  box-shadow: 0 1px 2px rgb(var(--ll-shadow) / calc(0.08 * var(--ll-shadow-a))), 0 26px 50px -22px rgb(var(--ll-shadow) / calc(0.4 * var(--ll-shadow-a)));
}
.menu ul { margin: 0; padding: 0; list-style: none; display: grid; }
.menu a { display: flex; align-items: center; min-height: 48px; padding: 0 14px; border-radius: 12px; font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 700; letter-spacing: -0.02em; color: var(--mk-ink); text-decoration: none; }
.menu a:hover { background: var(--mk-surface-2); }
@container (max-width: 820px) {
  .nav { display: none; }
