}
@container (max-width: 400px) { .tag { display: none; } }

/* ── Hero: the light table ──────────────────────────────────────────────────────────────────────────────── */
.hero { padding: clamp(12px, 1.8cqi, 22px) var(--ll-pad) 0; }
.table {
  position: relative;
  /* Fills the first screen, but never taller than 72 % of its width, so tablets get the landscape sheet. */
  height: min(clamp(420px, calc(100svh - 44px - 60px - 188px), 720px), 72cqi);
  border-radius: var(--mk-radius-l, 18px);
  isolation: isolate;
}
@container (max-width: 700px) { .table { height: clamp(460px, 138cqi, 640px); } }
.sheet { position: absolute; inset: 0; overflow: hidden; border-radius: inherit; }
/* The lens recipe's frame, fitted to the table (beats its own 16:9 sizing) and see-through until WebGL paints. */
.table .lensFrame.lensFrame {
  position: absolute;
  inset: 0;
  flex: none;
  aspect-ratio: auto;
  max-height: none;
  margin: 0;
  border-radius: inherit;
  background: transparent;
}
.table .lensFrame.lensFrame > [data-maquettekit-canvas] { border-radius: inherit; overflow: hidden; }
.table .lensFrame.lensFrame [data-maquettekit-fallback] .sheet { position: absolute; inset: 0; }
/* The lamp under the table warming up (entrance only; fill backwards, so CSS rests at 0). */
.lamp {
  position: absolute;
  inset: 0;
  z-index: 3;
  border-radius: inherit;
  background: radial-gradient(120% 120% at 42% 50%, color-mix(in oklab, var(--mk-bg) 40%, transparent), color-mix(in oklab, var(--mk-bg) 94%, transparent));
  opacity: 0;
  pointer-events: none;
}
.heroRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px 36px;
  padding: 22px 0 6px;
}
@container (min-width: 940px) {
  .heroRow { grid-template-columns: minmax(0, 1.3fr) auto minmax(0, 0.95fr); align-items: center; }
}
.intro { max-width: 56ch; margin: 0; font-size: 1rem; line-height: 1.55; color: var(--mk-ink-muted); text-wrap: pretty; }
.intro strong { color: var(--mk-ink); font-weight: 650; }
.ctas { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.lensHint { display: grid; justify-items: start; gap: 6px; }
.lensHint p { margin: 0; font-size: 0.875rem; line-height: 1.45; color: var(--mk-ink-muted); }
.keys { font-family: var(--mk-font-mono); font-size: 0.75rem; }

/* ── Buttons (lit by the lamp; pressed on a frame, released on spring.pop) ──────────────────────────────── */
.btnPrimary, .btnGhost {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 22px 0 24px;
  border-radius: 999px;
  font-size: 0.96875rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition:
    scale var(--ll-pop-ms, 400ms) var(--ll-pop, ease),
    box-shadow var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease),
    background-color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
}
.btnPrimary {
  border: 0;
  background: var(--mk-signal);
  color: var(--mk-on-signal);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.28),
    inset 0 -1px 0 rgb(0 0 0 / 0.12),
    calc(var(--lx) * -1.5px) calc(var(--ly) * -1.5px) 2px rgb(var(--ll-shadow) / calc(0.2 * var(--ll-shadow-a))),
    calc(var(--lx) * -12px) calc(var(--ly) * -12px) 26px -8px color-mix(in oklab, var(--mk-signal) 70%, transparent);
}
.btnPrimary span { transition: transform var(--ll-pop-ms, 400ms) var(--ll-pop, ease); }
.btnPrimary:hover span { transform: translateX(3px); }
.btnGhost {
  border: 1px solid var(--mk-line-strong);
  background: transparent;
  color: var(--mk-ink);
}
.btnGhost:hover { background: color-mix(in oklab, var(--mk-ink) 6%, transparent); }
.btnPrimary:active, .btnGhost:active { scale: 0.96; transition-duration: var(--mk-duration-instant, 90ms); }
.btnPrimary:active { box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), 0 1px 1px rgb(var(--ll-shadow) / 0.2); }
.btnPrimary:focus-visible, .btnGhost:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 3px; }
.textButton {
  min-height: 44px;
  padding: 0 2px;
  border: 0;
  background: none;
  color: var(--mk-ink);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, var(--mk-ink) 38%, transparent);
  text-underline-offset: 0.28em;
  cursor: pointer;
}
.textButton:hover { text-decoration-color: var(--mk-signal); }
.ghostButton {
  min-height: 46px;
  padding: 0 18px;
  border: 1px solid var(--mk-line-strong);
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink);
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
}
.ghostButton:hover { background: color-mix(in oklab, var(--mk-ink) 6%, transparent); }

/* ── Sections ───────────────────────────────────────────────────────────────────────────────────────────── */
.section { padding: clamp(80px, 11cqi, 148px) var(--ll-pad) 0; }
.sectionHead { display: grid; gap: 14px; margin-bottom: clamp(28px, 4cqi, 52px); }
.index {
  margin: 0;
  font-family: var(--mk-font-mono);
  font-size: 0.71875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mk-ink-muted);
}
.title h2, .archiveTitle, .feelTitle {
  max-width: 15ch;
  margin: 0;
  font-family: var(--mk-font-display);
  font-size: clamp(2.5rem, 6.6cqi, 5.75rem);
  font-weight: 760;
  line-height: 0.94;
  letter-spacing: -0.045em;
  color: inherit;
  text-wrap: balance;
}
.body { max-width: 52ch; margin: 0; font-size: 1rem; line-height: 1.55; color: var(--mk-ink-muted); }
.kicker { margin: 0; font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--mk-ink-muted); }
.fine { margin: 0; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted); }

/* ── Work ───────────────────────────────────────────────────────────────────────────────────────────────── */
.workGrid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(18px, 2.4cqi, 30px);
  margin: 0;
  padding: 0;
  list-style: none;
}
@container (min-width: 640px) {
  .workGrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .workCell[data-case='tidewater'] { grid-column: 1 / -1; }
}
@container (min-width: 1000px) {
  .workGrid { grid-template-columns: repeat(12, minmax(0, 1fr)); }
  .workCell[data-case='tidewater'], .workCell[data-case='crumb'] { grid-column: span 7; }
  .workCell[data-case='ferry'], .workCell[data-case='halden'] { grid-column: span 5; }
}
.workCell { min-width: 0; }
.card {
  --rx: 0;
  --ry: 0;
  --lift: 0;
  position: relative;
  height: 100%;
  perspective: 1300px;
}
.cardShadow {
  position: absolute;
  inset: 7% 4% 0;
  z-index: 0;
  border-radius: 22px;
  background: rgb(var(--ll-shadow) / calc(0.36 * var(--ll-shadow-a)));
  filter: blur(24px);
  opacity: calc(0.62 + var(--lift) * 0.38);
  transform:
    translate(calc(var(--lx) * -1 * (22px + var(--lift) * 26px)), calc(var(--ly) * -1 * (24px + var(--lift) * 30px)))
    scale(calc(0.96 + var(--lift) * 0.04));
  will-change: transform;
  pointer-events: none;
}
.cardBody {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-rows: auto 1fr;
  height: 100%;
  overflow: hidden;
  border-radius: var(--mk-radius-l, 18px);
  background: var(--mk-surface);
  box-shadow:
    0 0 0 1px var(--mk-line),
    inset 0 1px 0 rgb(255 255 255 / 0.06),
    calc(var(--lx) * -1px) calc(var(--ly) * -1.4px) calc(2px + var(--lift) * 2px) rgb(var(--ll-shadow) / calc((0.18 - var(--lift) * 0.1) * var(--ll-shadow-a)));
  transform: rotateX(calc(var(--rx) * 1deg)) rotateY(calc(var(--ry) * 1deg)) translateZ(calc(var(--lift) * 12px));
  transform-style: flat;
  transition: scale var(--ll-pop-ms, 400ms) var(--ll-pop, ease);
  will-change: transform;
}
.card[data-pressed] .cardBody { scale: 0.985; transition-duration: var(--mk-duration-instant, 90ms); }
.card[data-flying] .cardArt { visibility: hidden; }
.cardArt { position: relative; height: clamp(230px, 27cqi, 380px); overflow: hidden; }
.cardSheen {
  position: absolute;
  inset: -45%;
  z-index: 1;
  background: radial-gradient(closest-side, rgb(255 255 255 / 0.26), rgb(255 255 255 / 0.06) 55%, transparent 72%);
  opacity: calc(0.18 + var(--lift) * 0.5);
  transform: translate(calc(var(--lx) * 26% + var(--ry) * 1.8%), calc(var(--ly) * 26% - var(--rx) * 1.8%));
  mix-blend-mode: soft-light;
  pointer-events: none;
}
.cardText { display: grid; align-content: start; gap: 8px; padding: 18px 22px 22px; }
.cardKind { margin: 0; font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.09em; text-transform: uppercase; color: var(--mk-ink-muted); }
.cardTitle { margin: 0; }
.cardOpen {
  display: grid;
  gap: 4px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
/* The whole card opens the case: the button's hit area stretches over it (the heart sits above). */
.cardOpen::after { content: ''; position: absolute; inset: 0; z-index: 1; }
.cardOpen:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 5px; border-radius: 6px; }
.cardClient { font-family: var(--mk-font-display); font-size: clamp(1.375rem, 2.4cqi, 1.75rem); font-weight: 720; letter-spacing: -0.03em; line-height: 1.05; }
.cardLine { font-size: 0.96875rem; line-height: 1.4; color: var(--mk-ink-muted); }
.saveWrap { position: absolute; top: 12px; right: 12px; z-index: 3; display: inline-grid; border-radius: 50%; }
.save {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: color-mix(in oklab, var(--mk-surface) 88%, transparent);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  --lmi-ink: var(--mk-ink);
  --lmi-tint: var(--mk-signal);
  box-shadow:
    0 0 0 1px var(--mk-line),
    calc(var(--lx) * -1px) calc(var(--ly) * -1px) 2px rgb(var(--ll-shadow) / calc(0.16 * var(--ll-shadow-a))),
    calc(var(--lx) * -6px) calc(var(--ly) * -6px) 14px -4px rgb(var(--ll-shadow) / calc(0.26 * var(--ll-shadow-a)));
}

/* Case art: each still plays while its card is hovered or focused (full motion only). */
.artTide, .artFerry, .artType, .artCrumb { position: absolute; inset: 0; overflow: hidden; }
.artTide svg, .artFerry svg, .artCrumb svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.tideMark {
  position: absolute;
  left: 7%;
  top: 32%;
  display: flex;
  font-family: var(--mk-font-display);
  font-size: clamp(2.25rem, 7.2cqi, 5.5rem);
  font-stretch: 75%;
  font-weight: 800;
  letter-spacing: 0.01em;
  line-height: 1;
  color: #f3ecda;
}
.tideMark span { display: inline-block; transform: translateY(var(--y, 0)); }
.artFerry { background: #0b1022; }
.ferryTitle {
  position: absolute;
  left: 0;
  right: 0;
  top: 13%;
  text-align: center;
  font-family: var(--mk-font-serif);
  font-style: italic;
  font-size: clamp(1.75rem, 4cqi, 2.75rem);
  line-height: 1;
  color: #f4ecd8;
  text-shadow: 0 2px 18px rgb(0 0 0 / 0.5);
}
.ferryBeam { transform-origin: 318px 112px; transform-box: view-box; }
.artType { background: #efe8d8; }
.typeGlyph {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 21%;
  padding-left: 7%;
  font-family: var(--mk-font-display);
  font-size: clamp(6.5rem, 14cqi, 11.5rem);
  font-weight: 250;
  line-height: 1;
  letter-spacing: -0.04em;
  white-space: nowrap;
  color: #17150f;
}
.typeLine { position: absolute; left: 0; right: 0; top: var(--at); height: 0; border-top: 1px dashed #c2330ccc; }
.typeLine[data-solid] { border-top-style: solid; }
.typeLine span {
  position: absolute;
  right: 5%;
  bottom: 4px;
  font-family: var(--mk-font-mono);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
  color: #a3290a;
}
.typeAxis {
  position: absolute;
  left: 7%;
  right: 7%;
  bottom: 7%;
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mk-font-mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  color: #3d382d;
}
.typeTrack { position: relative; flex: 1; height: 2px; background: #17150f33; }
.typeKnob { position: absolute; top: -5px; left: 0; width: 12px; height: 12px; border-radius: 50%; background: #bf2f09; box-shadow: 0 1px 2px rgb(0 0 0 / 0.3); }
.artCrumb { background: #f0a24a; }
.crumbRolls { position: absolute; right: 7%; bottom: 17%; display: flex; gap: 8px; }
.crumbRolls i {
  width: clamp(22px, 3cqi, 34px);
  aspect-ratio: 1.35;
  border-radius: 50% 50% 44% 44%;
  background: radial-gradient(70% 60% at 40% 32%, #f3c27a, #c8742f 70%, #9c5520);
  box-shadow: 0 6px 8px -4px rgb(70 30 0 / 0.5);
  transform-origin: 50% 100%;
}

@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .card .tideLines path { animation: ll-tide 3.2s linear infinite; animation-delay: calc(var(--i) * -0.35s); animation-play-state: paused; }
  .root:not([data-reduced]) .card .tideMark span { animation: ll-swell 2.4s var(--mk-ease-inOut, ease-in-out) infinite alternate; animation-delay: calc(var(--i) * -0.16s); animation-play-state: paused; }
  .root:not([data-reduced]) .card .ferryBeam { animation: ll-beam 2.8s var(--mk-ease-inOut, ease-in-out) infinite alternate; animation-play-state: paused; }
  .root:not([data-reduced]) .card .ferryBoat { animation: ll-drift 6s var(--mk-ease-inOut, ease-in-out) infinite alternate; animation-play-state: paused; }
  .root:not([data-reduced]) .card .typeGlyph { transition: font-weight 1.1s var(--mk-ease-emphasized, ease), font-stretch 1.1s var(--mk-ease-emphasized, ease); }
  .root:not([data-reduced]) .card .typeKnob { transition: left 1.1s var(--mk-ease-emphasized, ease); }
  .root:not([data-reduced]) .card .crumbRolls i { animation: ll-hop 0.9s linear infinite; animation-delay: calc(var(--i) * 0.18s); animation-play-state: paused; }
  .root:not([data-reduced]) .card[data-play] :is(.tideLines path, .tideMark span, .ferryBeam, .ferryBoat, .crumbRolls i) { animation-play-state: running; }
  .root:not([data-reduced]) .card[data-play] .typeGlyph { font-weight: 800; font-stretch: 82%; }
  .root:not([data-reduced]) .card[data-play] .typeKnob { left: calc(100% - 12px); }
}
@keyframes ll-tide { to { transform: translateX(-96px); } }
@keyframes ll-swell { from { transform: translateY(calc(var(--y, 0) - 0.04em)); } to { transform: translateY(calc(var(--y, 0) * -1 + 0.04em)); } }
@keyframes ll-beam { from { transform: rotate(-9deg); } to { transform: rotate(7deg); } }
@keyframes ll-drift { from { transform: translateX(-12px); } to { transform: translateX(22px); } }
@keyframes ll-hop {
  0%, 100% { transform: translateY(0) scale(1, 1); }
  12% { transform: translateY(0) scale(1.16, 0.84); }
  30% { transform: translateY(-62%) scale(0.92, 1.1); }
  45% { transform: translateY(-80%) scale(1, 1); }
  70% { transform: translateY(0) scale(1.2, 0.8); }
  84% { transform: translateY(0) scale(0.97, 1.03); }
}

/* ── Case dialog ────────────────────────────────────────────────────────────────────────────────────────── */
.dialog {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 0;
  overflow: auto;
  border: 0;
  background: transparent;
  color: var(--mk-ink);
  container-type: inline-size;
}
.dialog::backdrop { background: rgb(10 9 7 / 0.62); }
.dialogInner {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  align-items: center;
  gap: 20px;
  width: min(1180px, 100%);
  min-height: 100%;
  margin: 0 auto;
  padding: clamp(16px, 4cqi, 48px);
}
@container (max-width: 820px) { .dialogInner { grid-template-columns: minmax(0, 1fr); align-content: start; } }
.dialogArt {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: var(--mk-radius-l, 18px);
  box-shadow: 0 30px 80px -30px rgb(0 0 0 / 0.7);
}
.dialogPanel {
  display: grid;
  gap: 14px;
  padding: clamp(20px, 3cqi, 34px);
  border-radius: var(--mk-radius-l, 18px);
  background: var(--mk-surface);
  box-shadow: 0 0 0 1px var(--mk-line), 0 30px 80px -30px rgb(0 0 0 / 0.7);
}
.dialogTitle { margin: 0; font-family: var(--mk-font-display); font-size: clamp(1.75rem, 4cqi, 2.6rem); font-weight: 760; letter-spacing: -0.035em; line-height: 1; }
.dialogLede { margin: 0; font-family: var(--mk-font-serif); font-style: italic; font-size: 1.375rem; line-height: 1.2; }
.dialogBody { margin: 0; font-size: 0.96875rem; line-height: 1.55; color: var(--mk-ink-muted); }
.dialogH4 { margin: 4px 0 8px; font-family: var(--mk-font-mono); font-size: 0.6875rem; font-weight: 500; letter-spacing: 0.1em; text-transform: uppercase; color: var(--mk-ink-muted); }
.dialogList { display: grid; gap: 6px; margin: 0; padding: 0; list-style: none; font-size: 0.9375rem; }
.dialogList li { display: flex; align-items: baseline; gap: 10px; }
.dialogList li::before { content: ''; flex: none; width: 7px; height: 7px; translate: 0 -1px; transform: rotate(45deg); background: var(--mk-signal); }
.dialogActions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; padding-top: 4px; }
.savePill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 46px;
  padding: 0 16px 0 10px;
  border-radius: 999px;
  box-shadow: inset 0 0 0 1px var(--mk-line-strong);
  font-size: 0.9375rem;
  font-weight: 600;
  --lmi-ink: var(--mk-ink);
  --lmi-tint: var(--mk-signal);
}
.savePill[aria-pressed='true'] { color: var(--mk-signal); box-shadow: inset 0 0 0 1px var(--mk-signal); }

/* ── Archive: a strip of film on the light table (always celluloid-dark) ─────────────────────────────────── */
.archive {
  --mk-ink: #f1ebde; --mk-ink-muted: #b0a998; --mk-line: #f1ebde26; --mk-line-strong: #f1ebde; --mk-focus: #8ab4ff;
  --mk-signal: #ff6a3d;
  --ll-frame-accent: #d4380d;
  margin-top: clamp(80px, 11cqi, 148px);
  padding: clamp(56px, 8cqi, 96px) 0 clamp(40px, 6cqi, 72px);
  background:
    radial-gradient(90% 140% at 20% 0%, #24201a, transparent 60%),
    #100f0c;
  box-shadow: inset 0 1px 0 var(--ll-band-edge), inset 0 -1px 0 var(--ll-band-edge);
  color: var(--mk-ink);
}
.archive .sectionHead { padding: 0 var(--ll-pad); }
.archiveHint { margin: 0; font-size: 0.9375rem; color: var(--mk-ink-muted); }
.filmFrame { position: relative; }
.film {
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  scroll-timeline: --ll-film x;
